	text := string(buf[:n])
	return strings.Count(text, "(*Raft).processLogs("), strings.Count(text, "(*Raft).restoreFromCommittedLogs(")
}

type caStartResult struct {
	returned             bool
	elapsed              time.Duration
	err                  string
	fsmApplied           int
	newBlockedProcess    int
	newBlockedRestoreLog int
}

// caStartup calls NewRaft in a separate goroutine and bounds the wait. A caller
// that observes no return cannot call Shutdown: NewRaft has not handed back the
// *Raft, which is the only owner of shutdownCh.
func caStartup(conf *Config, fsm *assuranceFSM, store *InmemCommitTrackingStore,
	snaps SnapshotStore, addr ServerAddress, timeout time.Duration) caStartResult {
	baseLogs, baseRestore := caStackMatches()
	_, trans := NewInmemTransport(addr)
	done := make(chan error, 1)
	var raft *Raft
	start := time.Now()
	go func() {
		var err error
		raft, err = NewRaft(conf, fsm, store, store, snaps, trans)
		done <- err
	}()
	var result caStartResult
	select {
	case err := <-done:
		result.returned = true
		result.elapsed = time.Since(start)
		if err != nil {
			result.err = err.Error()
		} else {
			defer func() { _ = raft.Shutdown().Error() }()
		}
	case <-time.After(timeout):
		result.elapsed = time.Since(start)
		result.err = "no return within observation window"
	}
	result.fsmApplied = fsm.count()
	logs, restore := caStackMatches()
	result.newBlockedProcess = logs - baseLogs
	result.newBlockedRestoreLog = restore - baseRestore
	return result
}

func caEmitCase(t *testing.T, name, mode string, timeout time.Duration,
	entries, stagedCommit, lastLog, snapshotIndex uint64) {
	caEmitCaseBatched(t, name, mode, timeout, entries, stagedCommit, lastLog, snapshotIndex, caMaxAppendEntries)
}

func caEmitCaseBatched(t *testing.T, name, mode string, timeout time.Duration,
	entries, stagedCommit, lastLog, snapshotIndex uint64, maxAppendEntries int) {
	replay := uint64(0)
	if stagedCommit > snapshotIndex {
		replay = stagedCommit - snapshotIndex
	}
	caEmit(t, map[string]interface{}{
		"event":                  "startup_case_" + name,
		"case":                   name,
		"mode":                   mode,
		"restore_committed_logs": true,
		"max_append_entries":     maxAppendEntries,
		"fsm_batch_capacity":     caFSMBatchCapacity,
		"entries":                entries,
		"staged_commit_index":    stagedCommit,
		"last_log_index":         lastLog,
		"snapshot_index":         snapshotIndex,
		"replay_entries":         replay,
		"replay_batches":         (replay + uint64(maxAppendEntries) - 1) / uint64(maxAppendEntries),
		"timeout_ms":             int(timeout / time.Millisecond),
	})
}

func caEmitResult(t *testing.T, name string, res caStartResult) {
	caEmit(t, map[string]interface{}{
		"event":                            "startup_result_" + name,
		"case":                             name,
		"returned":                         res.returned,
		"elapsed_ms":                       int(res.elapsed / time.Millisecond),
		"error":                            res.err,
		"fsm_applied_sampled":              res.fsmApplied,
		"new_goroutines_in_process_logs":   res.newBlockedProcess,
		"new_goroutines_in_restore_replay": res.newBlockedRestoreLog,
	})
}

func caSeededCase(t *testing.T, name string, entries uint64, timeout time.Duration) {
	caSeededCaseBatched(t, name, entries, caMaxAppendEntries, timeout)
}

func caSeededCaseBatched(t *testing.T, name string, entries uint64, maxAppendEntries int, timeout time.Duration) {
	store := NewInmemCommitTrackingStore()
	logs := make([]*Log, 0, entries)
	for i := uint64(1); i <= entries; i++ {
		logs = append(logs, &Log{Index: i, Term: 1, Type: LogCommand, Data: []byte("x")})
	}
	if err := store.StoreLogs(logs); err != nil {
		t.Fatalf("seed logs: %v", err)
	}
	if err := store.StageCommitIndex(entries); err != nil {
		t.Fatalf("stage commit index: %v", err)
	}
	lastLog, err := store.LastIndex()
	if err != nil {
		t.Fatalf("last index: %v", err)
	}
	caEmitCaseBatched(t, name, "seeded_commit_tracking_store", timeout, entries, entries, lastLog, 0, maxAppendEntries)
	conf := caConfig("node1")
	conf.MaxAppendEntries = maxAppendEntries
	res := caStartup(conf, &assuranceFSM{}, store, NewInmemSnapshotStore(), "node1", timeout)
	caEmitResult(t, name, res)
}

type caPrefix struct {
	store         *InmemCommitTrackingStore
	snaps         *InmemSnapshotStore
	stagedCommit  uint64
	lastLog       uint64
	snapshotIndex uint64
}

// caRealPrefix produces committed entries through a real single-node cluster and
// shuts it down, returning the retained stores.
func caRealPrefix(t *testing.T, commands int, takeSnapshot bool) caPrefix {
	store := NewInmemCommitTrackingStore()
	snaps := NewInmemSnapshotStore()
	conf := caConfig("node1")
	_, trans := NewInmemTransport("node1")
	configuration := Configuration{Servers: []Server{{Suffrage: Voter, ID: "node1", Address: trans.LocalAddr()}}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, &assuranceFSM{}, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("create producing raft: %v", err)
	}
	deadline := time.Now().Add(10 * time.Second)
	for r.Leader() == "" && time.Now().Before(deadline) {
		time.Sleep(2 * time.Millisecond)
	}
	if r.Leader() == "" {
		t.Fatalf("producing raft did not elect a leader")
	}
	var last ApplyFuture
	for i := 0; i < commands; i++ {
		last = r.Apply([]byte("x"), 5*time.Second)
	}
	if err := last.Error(); err != nil {
		t.Fatalf("apply through leader: %v", err)
	}
	if takeSnapshot {
		if err := r.Snapshot().Error(); err != nil {
			t.Fatalf("snapshot: %v", err)
		}
	}
	snapshotIndex := uint64(0)
	listed, err := snaps.List()
	if err != nil {
		t.Fatalf("list snapshots: %v", err)
	}
	if len(listed) > 0 {
		snapshotIndex = listed[0].Index
	}
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown producing raft: %v", err)
	}
	staged, err := store.GetCommitIndex()
	if err != nil {
		t.Fatalf("read staged commit index: %v", err)
	}
	lastLog, err := store.LastIndex()
	if err != nil {
		t.Fatalf("read last log index: %v", err)
	}
	return caPrefix{store: store, snaps: snaps, stagedCommit: staged, lastLog: lastLog, snapshotIndex: snapshotIndex}
}

func TestAssuranceRestoreCommittedLogsStartupReplay(t *testing.T) {
	// Controls run first so each trigger case reports newly blocked goroutines.
	t.Run("control_128_batches", func(t *testing.T) {
		caSeededCase(t, "control_128_batches", 8192, 20*time.Second)
	})
	t.Run("control_real_prefix_with_snapshot", func(t *testing.T) {
		prefix := caRealPrefix(t, caCommands, true)
		caEmitCase(t, "control_real_prefix_with_snapshot", "real_cluster_restart", 20*time.Second,
			caCommands, prefix.stagedCommit, prefix.lastLog, prefix.snapshotIndex)
		conf := caConfig("node1")
		res := caStartup(conf, &assuranceFSM{}, prefix.store, prefix.snaps, "node1", 20*time.Second)
		caEmitResult(t, "control_real_prefix_with_snapshot", res)
	})
	t.Run("control_same_entries_larger_batches", func(t *testing.T) {
		// Identical committed entry count to trigger_129_batches; only the batch
		// size differs, so 8193 entries need 9 batches instead of 129.
		caSeededCaseBatched(t, "control_same_entries_larger_batches", 8193, 1024, 20*time.Second)
	})
	t.Run("control_128_batches_at_1024", func(t *testing.T) {
		// 131072 entries at MaxAppendEntries=1024 is exactly 128 batches.
		caSeededCaseBatched(t, "control_128_batches_at_1024", 131072, 1024, 20*time.Second)
	})
	t.Run("trigger_129_batches_at_1024", func(t *testing.T) {
		// One entry past the same boundary: 129 batches.
		caSeededCaseBatched(t, "trigger_129_batches_at_1024", 131073, 1024, 5*time.Second)
	})
	t.Run("trigger_129_batches", func(t *testing.T) {
		caSeededCase(t, "trigger_129_batches", 8193, 5*time.Second)
	})
	t.Run("trigger_real_prefix_no_snapshot", func(t *testing.T) {
		prefix := caRealPrefix(t, caCommands, false)
		caEmitCase(t, "trigger_real_prefix_no_snapshot", "real_cluster_restart", 5*time.Second,
			caCommands, prefix.stagedCommit, prefix.lastLog, prefix.snapshotIndex)
		conf := caConfig("node1")
		res := caStartup(conf, &assuranceFSM{}, prefix.store, prefix.snaps, "node1", 5*time.Second)
		caEmitResult(t, "trigger_real_prefix_no_snapshot", res)
	})
}

harness.source:
package raft

// Construction notes:
//   * Two real members are bootstrapped as voters {A, B} over in-memory
//     transports; the leading member's log store fails exactly the write that
//     would carry the configuration entry removing the other member.
//   * The harness then records whether the failed change left an in-memory
//     configuration ahead of the stored log, and whether the leader can later
//     commit a client command without the other member having it.

import (
	"encoding/json"
	"fmt"
	"io"
	"sync"
	"testing"
	"time"
)

func phEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

type failStore struct {
	*InmemStore
	mu       sync.Mutex
	failNext bool
}

func newFailStore() *failStore { return &failStore{InmemStore: NewInmemStore()} }

func (f *failStore) StoreLogs(logs []*Log) error {
	f.mu.Lock()
	fail := f.failNext
	f.failNext = false
	f.mu.Unlock()
	if fail {
		return errInjected
	}
	return f.InmemStore.StoreLogs(logs)
}

type errType string

func (e errType) Error() string { return string(e) }

const errInjected = errType("injected store failure")

type phFSM struct{}

func (f *phFSM) Apply(*Log) interface{}         { return nil }
func (f *phFSM) Snapshot() (FSMSnapshot, error) { return &phSnap{}, nil }
func (f *phFSM) Restore(io.ReadCloser) error    { return nil }

type phSnap struct{}

func (s *phSnap) Persist(SnapshotSink) error { return nil }
func (s *phSnap) Release()                   {}

func phantomRun(t *testing.T, caseName string, grow bool) {
	conf := inmemConfig(t)
	conf.HeartbeatTimeout = 300 * time.Millisecond
	conf.ElectionTimeout = 300 * time.Millisecond
	conf.LeaderLeaseTimeout = 300 * time.Millisecond

	addrA, transA := NewInmemTransport("A")
	addrB, transB := NewInmemTransport("B")
	transA.Connect(addrB, transB)
	transB.Connect(addrA, transA)

	storeA, storeB := newFailStore(), newFailStore()
	snapsA, snapsB := NewInmemSnapshotStore(), NewInmemSnapshotStore()
	cfg := Configuration{Servers: []Server{
		{Suffrage: Voter, ID: "A", Address: addrA},
		{Suffrage: Voter, ID: "B", Address: addrB},
	}}
	confA := *conf
	confA.LocalID = "A"
	confB := *conf
	confB.LocalID = "B"
	if err := BootstrapCluster(&confA, storeA, storeA, snapsA, transA, cfg); err != nil {
		t.Fatalf("bootstrap A: %v", err)
	}
	if err := BootstrapCluster(&confB, storeB, storeB, snapsB, transB, cfg); err != nil {
		t.Fatalf("bootstrap B: %v", err)
	}
	rA, err := NewRaft(&confA, &phFSM{}, storeA, storeA, snapsA, transA)
	if err != nil {
		t.Fatalf("raft A: %v", err)
	}
	defer func() { _ = rA.Shutdown().Error() }()
	rB, err := NewRaft(&confB, &phFSM{}, storeB, storeB, snapsB, transB)
	if err != nil {
		t.Fatalf("raft B: %v", err)
	}
	defer func() { _ = rB.Shutdown().Error() }()

	deadline := time.Now().Add(10 * time.Second)
	for rA.Leader() == "" && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	rL, rP := rA, rB
	stL, stP := storeA, storeB
	peerID := ServerID("B")
	if rA.Leader() == "B" {
		rL, rP = rB, rA
		stL, stP = storeB, storeA
		peerID = "A"
	}
	_ = rP
	t.Logf("leader=%v follower-to-remove=%v", rL.Leader(), peerID)

	stL.mu.Lock()
	stL.failNext = true
	stL.mu.Unlock()
	var errRemove error
	if grow {
		errRemove = rL.AddVoter("C", "C", 0, 5*time.Second).Error()
	} else {
		errRemove = rL.RemoveServer(peerID, 0, 5*time.Second).Error()
	}
	lastLogL, _ := stL.LastIndex()
	latestCfg := rL.getLatestConfiguration()
	t.Logf("remove err=%v stateL=%v latestIndex=%d latestServers=%v lastLogL=%d",
		errRemove, rL.State(), rL.configurations.latestIndex, latestCfg.Servers, lastLogL)

	deadline = time.Now().Add(10 * time.Second)
	for rL.State() != Leader && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	stateL := rL.State()
	reElected := stateL == Leader
	applyErr := rL.Apply([]byte("phantom"), 3*time.Second).Error()
	commitL := rL.CommitIndex()
	lastL, _ := stL.LastIndex()
	lastP, _ := stP.LastIndex()
	phantomServers := fmt.Sprintf("%v", latestCfg.Servers)
	latestIndex := rL.configurations.latestIndex
	phEmit(t, map[string]interface{}{
		"event":                    "phantom_case_" + caseName,
		"case":                     caseName,
		"members":                  2,
		"failure_injected":         true,
		"removed_peer":             string(peerID),
		"latest_index_after_fail":  latestIndex,
		"last_log_index_after_fail": lastLogL,
		"phantom_servers":          phantomServers,
	})
	phEmit(t, map[string]interface{}{
		"event":                     "phantom_result_" + caseName,
		"case":                      caseName,
		"remove_error":              fmt.Sprintf("%v", errRemove),
		"remove_failed":             errRemove != nil,
		"latest_index_exceeds_log":  latestIndex > lastLogL,
		"re_elected":                reElected,
		"apply_ok":                  applyErr == nil,
		"commit_index":              commitL,
		"leader_last_index":         lastL,
		"peer_last_index":           lastP,
		"commit_without_peer":       applyErr == nil && lastP < commitL,
	})
	t.Logf("stateL=%v applyErr=%v commitL=%d lastL=%d lastPeer=%d", stateL, applyErr, commitL, lastL, lastP)

	// Restart the phantom leader from its own stores and see whether the lone
	// commit is retained and whether the peer catches up under the log-derived
	// configuration.
	confRestart := rL.config()
	confRestart.Logger = nil
	restartAddr := rL.localAddr
	logsRestart, stableRestart, snapsRestart := stL, stL, rL.snapshots
	_ = rL.Shutdown()
	_, transRestart := NewInmemTransport(restartAddr)
	// Wire the restarted node back to the surviving peer: the peer's routing
	// table still points at the previous transport object.
	transRestart.Connect(rP.localAddr, rP.trans.(*InmemTransport))
	rP.trans.(*InmemTransport).Disconnect(restartAddr)
	rP.trans.(*InmemTransport).Connect(restartAddr, transRestart)
	restarted, rerr := NewRaft(&confRestart, &phFSM{}, logsRestart, stableRestart, snapsRestart, transRestart)
	restartOK := rerr == nil
	becameLeader := false
	if restartOK {
		defer func() { _ = restarted.Shutdown().Error() }()
		dl := time.Now().Add(10 * time.Second)
		for time.Now().Before(dl) {
			if restarted.State() == Leader {
				becameLeader = true
				break
			}
			time.Sleep(20 * time.Millisecond)
		}
	}
	lastPeerAfter, _ := stP.LastIndex()
	lastLAfter, _ := stL.LastIndex()
	phEmit(t, map[string]interface{}{
		"event":                 "phantom_restart_" + caseName,
		"case":                  caseName,
		"restart_ok":            restartOK,
		"restarted_as_leader":   becameLeader,
		"leader_last_index":     lastLAfter,
		"peer_last_index":       lastPeerAfter,
		"peer_caught_up":        lastPeerAfter >= commitL,
		"lone_commit_retained":  lastLAfter >= commitL,
	})
}

func TestAssurancePhantomConfiguration(t *testing.T) {
	t.Run("shrink_failed_write", func(t *testing.T) { phantomRun(t, "shrink_failed_write", false) })
	t.Run("grow_failed_write", func(t *testing.T) { phantomRun(t, "grow_failed_write", true) })
}

