harness.source:
package raft

// Construction notes:
//   * Five real nodes over in-memory transports: voters A, B, C and non-voters
//     D, E, all bootstrapped with the same configuration and a recording FSM.
//   * The leader writes "v1" and every node applies it. The leader is then
//     partitioned from the two other voters and keeps only the non-voters
//     reachable, so the committed voter quorum cannot answer it.
//   * Immediately after the partition the old leader is asked to verify itself,
//     which is the check a caller performs before serving a read. The trigger
//     keeps the non-voters reachable; the control also cuts them, leaving the old
//     leader with no possible supporter.
//   * The two remaining voters then elect a new leader and commit "v2". Once that
//     has happened the old leader is asked to verify itself again and its state
//     machine is read.
//   * The decisive observation is whether verification can still succeed after
//     the majority has moved on, which is what a stale verified read needs.

import (
	"encoding/json"
	"fmt"
	"io"
	"sync"
	"testing"
	"time"
)

func srEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

type srFSM struct {
	mu   sync.Mutex
	vals []string
}

func (f *srFSM) Apply(l *Log) interface{} {
	f.mu.Lock()
	f.vals = append(f.vals, string(l.Data))
	f.mu.Unlock()
	return nil
}

func (f *srFSM) last() string {
	f.mu.Lock()
	defer f.mu.Unlock()
	if len(f.vals) == 0 {
		return ""
	}
	return f.vals[len(f.vals)-1]
}

func (f *srFSM) Snapshot() (FSMSnapshot, error) { return &srSnap{}, nil }
func (f *srFSM) Restore(io.ReadCloser) error    { return nil }

type srSnap struct{}

func (s *srSnap) Persist(SnapshotSink) error { return nil }
func (s *srSnap) Release()                   {}

func srWaitLeader(t *testing.T, nodes []*Raft, want *Raft, timeout time.Duration) *Raft {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		for _, r := range nodes {
			if r == want {
				continue
			}
			if st := r.State(); st == Leader {
				return r
			}
		}
		time.Sleep(20 * time.Millisecond)
	}
	return nil
}

func srVerify(r *Raft, timeout time.Duration) (bool, string, bool) {
	done := make(chan error, 1)
	go func() { done <- r.VerifyLeader().Error() }()
	select {
	case err := <-done:
		if err != nil {
			return false, err.Error(), true
		}
		return true, "", true
	case <-time.After(timeout):
		return false, "no completion", false
	}
}

func srRun(t *testing.T, caseName string, cutNonvoters bool) {
	base := inmemConfig(t)
	// The lease may not exceed the heartbeat timeout. All members share a
	// one-second heartbeat and lease; the voters' election timeouts are staggered
	// so that, whichever member leads, the two remaining voters do not campaign in
	// lockstep and split the vote after the partition.
	base.HeartbeatTimeout = time.Second
	base.LeaderLeaseTimeout = time.Second
	electionTimeouts := map[string]time.Duration{
		"A": 1100 * time.Millisecond,
		"B": 2 * time.Second,
		"C": 3 * time.Second,
		"D": 3 * time.Second,
		"E": 3 * time.Second,
	}

	ids := []string{"A", "B", "C", "D", "E"}
	addrs := make(map[string]ServerAddress, len(ids))
	trans := make(map[string]*InmemTransport, len(ids))
	for _, id := range ids {
		a, tr := NewInmemTransport(ServerAddress(id))
		addrs[id] = a
		trans[id] = tr
	}
	for _, i := range ids {
		for _, j := range ids {
			if i != j {
				trans[i].Connect(addrs[j], trans[j])
			}
		}
	}

	servers := []Server{
		{Suffrage: Voter, ID: "A", Address: addrs["A"]},
		{Suffrage: Voter, ID: "B", Address: addrs["B"]},
		{Suffrage: Voter, ID: "C", Address: addrs["C"]},
		{Suffrage: Nonvoter, ID: "D", Address: addrs["D"]},
		{Suffrage: Nonvoter, ID: "E", Address: addrs["E"]},
	}
	cfg := Configuration{Servers: servers}

	nodes := make(map[string]*Raft, len(ids))
	fsms := make(map[string]*srFSM, len(ids))
	stores := make(map[string]*InmemStore, len(ids))
	snaps := make(map[string]*InmemSnapshotStore, len(ids))
	for _, id := range ids {
		conf := *base
		conf.LocalID = ServerID(id)
		conf.ElectionTimeout = electionTimeouts[id]
		store := NewInmemStore()
		snap := NewInmemSnapshotStore()
		if err := BootstrapCluster(&conf, store, store, snap, trans[id], cfg); err != nil {
			t.Fatalf("bootstrap %s: %v", id, err)
		}
		fsm := &srFSM{}
		r, err := NewRaft(&conf, fsm, store, store, snap, trans[id])
		if err != nil {
			t.Fatalf("raft %s: %v", id, err)
		}
		defer func(r *Raft) { _ = r.Shutdown().Error() }(r)
		nodes[id] = r
		fsms[id] = fsm
		stores[id] = store
		snaps[id] = snap
	}

	all := []*Raft{nodes["A"], nodes["B"], nodes["C"], nodes["D"], nodes["E"]}
	leader := srWaitLeader(t, all, nil, 10*time.Second)
	if leader == nil {
		t.Fatalf("no leader formed")
	}
	leaderID := string(leader.localID)

	if err := leader.Apply([]byte("v1"), 3*time.Second).Error(); err != nil {
		t.Fatalf("initial apply: %v", err)
	}
	time.Sleep(300 * time.Millisecond)

	// Partition the leader from the other two voters, and optionally from the
	// non-voters as well.
	leaderTrans := trans[leaderID]
	for _, id := range ids {
		if id == leaderID {
			continue
		}
		isVoter := id == "A" || id == "B" || id == "C"
		// Always cut the other voters; in the control, cut the non-voters too.
		if isVoter || cutNonvoters {
			leaderTrans.Disconnect(addrs[id])
			trans[id].Disconnect(addrs[leaderID])
		}
	}

	srEmit(t, map[string]interface{}{
		"event":               "sr_case_" + caseName,
		"case":                caseName,
		"members":             5,
		"voters":              3,
		"nonvoters":           2,
		"leader":              leaderID,
		"voters_reachable":    1,
		"nonvoters_reachable": map[bool]int{true: 0, false: 2}[cutNonvoters],
		"initial_value":       "v1",
		"leader_value":        fsms[leaderID].last(),
	})

	// While the old leader still believes it leads: verify, then write.
	cutAt := time.Now()
	verifyOK, verifyErr, verifyCompleted := srVerify(leader, 2*time.Second)
	msToVerify := int(time.Since(cutAt) / time.Millisecond)

	// The majority side elects a new leader and commits a different value.
	newLeader := srWaitLeader(t, all, leader, 12*time.Second)
	newLeaderID := ""
	newApplyOK := false
	newValue := ""
	if newLeader != nil {
		newLeaderID = string(newLeader.localID)
		newApplyOK = newLeader.Apply([]byte("v2"), 3*time.Second).Error() == nil
		time.Sleep(300 * time.Millisecond)
		newValue = fsms[newLeaderID].last()
	}
	msToNewLeader := -1
	if newLeaderID != "" {
		msToNewLeader = int(time.Since(cutAt) / time.Millisecond)
	}

	// Can the old leader still verify itself now that the majority has a leader?
	verifyAfterOK, verifyAfterErr, _ := srVerify(leader, 2*time.Second)
	oldValueBeforeHeal := fsms[leaderID].last()

	// Heal the partition and let the new leader's log reach the old one.
	for _, id := range ids {
		if id == leaderID {
			continue
		}
		leaderTrans.Connect(addrs[id], trans[id])
		trans[id].Connect(addrs[leaderID], leaderTrans)
	}
	time.Sleep(1500 * time.Millisecond)

	oldValue := fsms[leaderID].last()
	srEmit(t, map[string]interface{}{
		"event":             "sr_result_" + caseName,
		"case":              caseName,
		"old_leader":        leaderID,
		"old_leader_state":  leader.State().String(),
		"verify_completed":  verifyCompleted,
		"verify_after_partition_ok": verifyOK,
		"verify_error":      verifyErr,
		"ms_to_verify":      msToVerify,
		"new_leader":        newLeaderID,
		"new_apply_ok":      newApplyOK,
		"ms_to_new_leader":  msToNewLeader,
		"new_leader_value":  newValue,
		"verify_after_failover_ok": verifyAfterOK,
		"verify_after_failover_error": verifyAfterErr,
		"old_value_before_heal": oldValueBeforeHeal,
		"old_leader_value":  oldValue,
		"stale_verified_read": verifyAfterOK && newValue != "" && oldValueBeforeHeal != newValue,
	})
	t.Logf("case=%v old=%v verifyBefore=%v ms=%d newLeader=%v msNew=%d verifyAfter=%v errAfter=%q oldBeforeHeal=%q newValue=%q",
		caseName, leaderID, verifyOK, msToVerify, newLeaderID, msToNewLeader, verifyAfterOK, verifyAfterErr, oldValueBeforeHeal, newValue)
}

func TestAssuranceVerifyStaleRead(t *testing.T) {
	t.Run("trigger_nonvoters_connected", func(t *testing.T) {
		srRun(t, "trigger_nonvoters_connected", false)
	})
	t.Run("control_all_cut", func(t *testing.T) {
		srRun(t, "control_all_cut", true)
	})
}

package raft

// Construction notes:
//   * The startup replay pushes one commitTuple per MaxAppendEntries entries into
//     r.fsmMutateCh, whose capacity is fixed at 128 in the captured code, and the
//     only consumer is started after NewRaft returns.
//   * Earlier work measured the boundary at MaxAppendEntries=64 (8192 entries)
//     and MaxAppendEntries=1024 (131072 entries). This harness moves the batch
//     size to its smallest legal value, 1, so the predicted boundary is 128
//     entries rather than 8192.
//   * Cases: exactly 128 replayed entries, which is 128 batches and should
//     return, and 129 entries, which is 129 batches and should not.

import (
	"encoding/json"
	"fmt"
	"io"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

const rbBatchCapacity = 128

type rbFSM struct {
	mu      sync.Mutex
	applied int
}

func (f *rbFSM) Apply(*Log) interface{} {
	f.mu.Lock()
	f.applied++
	f.mu.Unlock()
	return nil
}

func (f *rbFSM) Snapshot() (FSMSnapshot, error) { return &rbSnapshot{}, nil }

func (f *rbFSM) Restore(io.ReadCloser) error {
	f.mu.Lock()
	f.applied = 0
	f.mu.Unlock()
	return nil
}

func (f *rbFSM) count() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.applied
}

type rbSnapshot struct{}

func (s *rbSnapshot) Persist(SnapshotSink) error { return nil }
func (s *rbSnapshot) Release()                  {}

func rbEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func rbConfig(id string) *Config {
	conf := DefaultConfig()
	conf.LocalID = ServerID(id)
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.HeartbeatTimeout = 50 * time.Millisecond
	conf.ElectionTimeout = 50 * time.Millisecond
	conf.LeaderLeaseTimeout = 50 * time.Millisecond
	conf.CommitTimeout = 5 * time.Millisecond
	conf.RestoreCommittedLogs = true
	conf.MaxAppendEntries = 1
	return conf
}

func rbBlockedProducers() int {
	buf := make([]byte, 1<<22)
	n := runtime.Stack(buf, true)
	return strings.Count(string(buf[:n]), "(*Raft).processLogs(")
}

type rbResult struct {
	returned    bool
	elapsed     time.Duration
	err         string
	applied     int
	blockedDiff int
}

func rbStart(conf *Config, fsm *rbFSM, store *InmemCommitTrackingStore,
	snaps SnapshotStore, addr ServerAddress, timeout time.Duration) rbResult {
	base := rbBlockedProducers()
	_, trans := NewInmemTransport(addr)
	done := make(chan error, 1)
	var raft *Raft
	start := time.Now()
	go func() {
		var err error
		raft, err = NewRaft(conf, fsm, store, store, snaps, trans)
		done <- err
	}()
	var res rbResult
	select {
	case err := <-done:
		res.returned = true
		res.elapsed = time.Since(start)
		if err != nil {
			res.err = err.Error()
		} else {
			defer func() { _ = raft.Shutdown().Error() }()
		}
	case <-time.After(timeout):
		res.elapsed = time.Since(start)
		res.err = "no return within observation window"
	}
	res.applied = fsm.count()
	res.blockedDiff = rbBlockedProducers() - base
	return res
}

func rbRun(t *testing.T, name string, entries uint64, timeout time.Duration) {
	store := NewInmemCommitTrackingStore()
	logs := make([]*Log, 0, entries)
	for i := uint64(1); i <= entries; i++ {
		logs = append(logs, &Log{Index: i, Term: 1, Type: LogCommand, Data: []byte("x")})
	}
	if err := store.StoreLogs(logs); err != nil {
		t.Fatalf("seed logs: %v", err)
	}
	if err := store.StageCommitIndex(entries); err != nil {
		t.Fatalf("stage commit index: %v", err)
	}
	lastLog, err := store.LastIndex()
	if err != nil {
		t.Fatalf("last index: %v", err)
	}
	rbEmit(t, map[string]interface{}{
		"event":                  "rb_case_" + name,
		"case":                   name,
		"mode":                   "seeded_commit_tracking_store",
		"restore_committed_logs": true,
		"max_append_entries":     1,
		"fsm_batch_capacity":     rbBatchCapacity,
		"entries":                entries,
		"staged_commit_index":    entries,
		"last_log_index":         lastLog,
		"replay_entries":         entries,
		"replay_batches":         entries,
		"timeout_ms":             int(timeout / time.Millisecond),
	})
	res := rbStart(rbConfig("node1"), &rbFSM{}, store, NewInmemSnapshotStore(), "node1", timeout)
	rbEmit(t, map[string]interface{}{
		"event":                          "rb_result_" + name,
		"case":                           name,
		"returned":                       res.returned,
		"elapsed_ms":                     int(res.elapsed / time.Millisecond),
		"error":                          res.err,
		"fsm_applied_sampled":            res.applied,
		"new_goroutines_in_process_logs": res.blockedDiff,
	})
	t.Logf("case=%s entries=%d returned=%v elapsed=%v err=%q", name, entries, res.returned, res.elapsed, res.err)
}

func TestAssuranceRestoreBatchOne(t *testing.T) {
	t.Run("control_128_batches_at_1", func(t *testing.T) {
		rbRun(t, "control_128_batches_at_1", 128, 10*time.Second)
	})
	t.Run("trigger_129_batches_at_1", func(t *testing.T) {
		rbRun(t, "trigger_129_batches_at_1", 129, 5*time.Second)
	})
}

package raft

// Construction notes:
//   * A real single-node cluster commits a first batch, takes a snapshot, then
//     commits a second batch, and is shut down. On restart the replay is the gap
//     between the snapshot index and the staged commit index, so the snapshot
//     shortens the replay instead of eliminating it.
//   * Short case: the second batch is small enough that the gap needs a handful
//     of FSM batches, which is the recovery region earlier work could only infer.
//   * Long case: the second batch pushes the gap past 128 batches at the default
//     MaxAppendEntries=64, which must block NewRaft.

import (
	"encoding/json"
	"fmt"
	"io"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

// Values taken from DefaultConfig(); recorded in every event so the boundary
// arithmetic stays inspectable.
const (
	rcMaxAppendEntries = 64
	rcBatchCapacity    = 128
)

type rcFSM struct {
	mu      sync.Mutex
	applied int
}

func (f *rcFSM) Apply(*Log) interface{} {
	f.mu.Lock()
	f.applied++
	f.mu.Unlock()
	return nil
}

func (f *rcFSM) Snapshot() (FSMSnapshot, error) { return &rcSnapshot{}, nil }

func (f *rcFSM) Restore(io.ReadCloser) error {
	f.mu.Lock()
	f.applied = 0
	f.mu.Unlock()
	return nil
}

func (f *rcFSM) count() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.applied
}

type rcSnapshot struct{}

func (s *rcSnapshot) Persist(SnapshotSink) error { return nil }
func (s *rcSnapshot) Release()                  {}

func rcEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func rcConfig(id string) *Config {
	conf := DefaultConfig()
	conf.LocalID = ServerID(id)
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.HeartbeatTimeout = 50 * time.Millisecond
	conf.ElectionTimeout = 50 * time.Millisecond
	conf.LeaderLeaseTimeout = 50 * time.Millisecond
	conf.CommitTimeout = 5 * time.Millisecond
	conf.RestoreCommittedLogs = true
	return conf
}

func rcBlockedProducers() int {
	buf := make([]byte, 1<<22)
	n := runtime.Stack(buf, true)
	return strings.Count(string(buf[:n]), "(*Raft).processLogs(")
}

type rcPrefix struct {
	store         *InmemCommitTrackingStore
	snaps         *InmemSnapshotStore
	stagedCommit  uint64
	lastLog       uint64
	snapshotIndex uint64
}

func rcBuildPrefix(t *testing.T, firstBatch, secondBatch int) rcPrefix {
	store := NewInmemCommitTrackingStore()
	snaps := NewInmemSnapshotStore()
	conf := rcConfig("node1")
	_, trans := NewInmemTransport("node1")
	configuration := Configuration{Servers: []Server{{Suffrage: Voter, ID: "node1", Address: trans.LocalAddr()}}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, &rcFSM{}, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("create producing raft: %v", err)
	}
	deadline := time.Now().Add(10 * time.Second)
	for r.Leader() == "" && time.Now().Before(deadline) {
		time.Sleep(2 * time.Millisecond)
	}
	if r.Leader() == "" {
		t.Fatalf("producing raft did not elect a leader")
	}
	apply := func(n int) {
		var last ApplyFuture
		for i := 0; i < n; i++ {
			last = r.Apply([]byte("x"), 5*time.Second)
		}
		if err := last.Error(); err != nil {
			t.Fatalf("apply: %v", err)
		}
	}
	apply(firstBatch)
	if err := r.Snapshot().Error(); err != nil {
		t.Fatalf("snapshot: %v", err)
	}
	apply(secondBatch)
	snapshotIndex := uint64(0)
	listed, err := snaps.List()
	if err != nil {
		t.Fatalf("list snapshots: %v", err)
	}
	if len(listed) > 0 {
		snapshotIndex = listed[0].Index
	}
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown: %v", err)
	}
	staged, err := store.GetCommitIndex()
	if err != nil {
		t.Fatalf("staged commit: %v", err)
	}
	lastLog, err := store.LastIndex()
	if err != nil {
		t.Fatalf("last log: %v", err)
	}
	return rcPrefix{store: store, snaps: snaps, stagedCommit: staged, lastLog: lastLog, snapshotIndex: snapshotIndex}
}

func rcRun(t *testing.T, name string, firstBatch, secondBatch int, timeout time.Duration) {
	prefix := rcBuildPrefix(t, firstBatch, secondBatch)
	replay := uint64(0)
	if prefix.stagedCommit > prefix.snapshotIndex {
		replay = prefix.stagedCommit - prefix.snapshotIndex
	}
	batches := (replay + rcMaxAppendEntries - 1) / rcMaxAppendEntries
	rcEmit(t, map[string]interface{}{
		"event":               "rc_case_" + name,
		"case":                name,
		"mode":                "real_cluster_restart_with_mid_snapshot",
		"restore_committed_logs": true,
		"first_batch":         firstBatch,
		"second_batch":        secondBatch,
		"snapshot_index":      prefix.snapshotIndex,
		"staged_commit_index": prefix.stagedCommit,
		"last_log_index":      prefix.lastLog,
		"replay_entries":      replay,
		"replay_batches":      batches,
		"max_append_entries":  rcMaxAppendEntries,
		"fsm_batch_capacity":  rcBatchCapacity,
		"timeout_ms":          int(timeout / time.Millisecond),
	})
	base := rcBlockedProducers()
	conf := rcConfig("node1")
	_, trans := NewInmemTransport("node1")
	done := make(chan error, 1)
	var raft *Raft
	start := time.Now()
	go func() {
		var err error
		raft, err = NewRaft(conf, &rcFSM{}, prefix.store, prefix.store, prefix.snaps, trans)
		done <- err
	}()
	returned := false
	errText := ""
	select {
	case err := <-done:
		returned = true
		if err != nil {
			errText = err.Error()
		} else {
			defer func() { _ = raft.Shutdown().Error() }()
		}
	case <-time.After(timeout):
		errText = "no return within observation window"
	}
	elapsed := time.Since(start)
	blocked := rcBlockedProducers() - base
	rcEmit(t, map[string]interface{}{
		"event":                  "rc_result_" + name,
		"case":                   name,
		"mode":                   "real_cluster_restart_with_mid_snapshot",
		"first_batch":            firstBatch,
		"second_batch":           secondBatch,
		"snapshot_index":         prefix.snapshotIndex,
		"staged_commit_index":    prefix.stagedCommit,
		"last_log_index":         prefix.lastLog,
		"replay_entries":         replay,
		"replay_batches":         batches,
		"max_append_entries":     rcMaxAppendEntries,
		"fsm_batch_capacity":     rcBatchCapacity,
		"returned":               returned,
		"elapsed_ms":             int(elapsed / time.Millisecond),
		"error":                  errText,
		"new_goroutines_in_process_logs": blocked,
	})
	t.Logf("case=%s snapshot=%d staged=%d replay=%d batches=%d returned=%v err=%q",
		name, prefix.snapshotIndex, prefix.stagedCommit, replay, batches, returned, errText)
}

func TestAssuranceRestorePartialReplay(t *testing.T) {
	t.Run("control_short_replay_after_snapshot", func(t *testing.T) {
		rcRun(t, "control_short_replay_after_snapshot", 200, 200, 10*time.Second)
	})
	t.Run("trigger_long_replay_after_snapshot", func(t *testing.T) {
		rcRun(t, "trigger_long_replay_after_snapshot", 200, 8300, 5*time.Second)
	})
}

package raft

// Construction notes:
//   * Same follower setup and race as the two-point jitter probe, but the stable
//     store's current-term write is delayed by a uniform interval drawn from
//     [0, maxDelay), and the harness sweeps maxDelay instead of testing a single
//     value: 0, 250 us, 500 us, 1 ms and 2 ms, 200 attempts each.
//   * Each attempt issues one fast-path heartbeat carrying cur+1 concurrently
//     with a term cur+2 AppendEntries through the real consumer path, then
//     records whether the persisted term ended below cur+2.
//   * The point is the shape of the rate against store latency, which the
//     target's own divergence note ties to heartbeat concurrency.

import (
	"encoding/json"
	"fmt"
	"io"
	"math/rand"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

type sweepStore struct {
	*InmemStore
	mu       sync.Mutex
	maxDelay time.Duration
	rnd      *rand.Rand
}

func newSweepStore(maxDelay time.Duration) *sweepStore {
	return &sweepStore{InmemStore: NewInmemStore(), maxDelay: maxDelay, rnd: rand.New(rand.NewSource(11))}
}

func (s *sweepStore) SetUint64(key []byte, val uint64) error {
	if string(key) == string(keyCurrentTerm) && s.maxDelay > 0 {
		s.mu.Lock()
		d := time.Duration(s.rnd.Int63n(int64(s.maxDelay)))
		s.mu.Unlock()
		time.Sleep(d)
	}
	return s.InmemStore.SetUint64(key, val)
}

type sweepFSM struct{ mu sync.Mutex }

func (f *sweepFSM) Apply(*Log) interface{}         { return nil }
func (f *sweepFSM) Snapshot() (FSMSnapshot, error) { return &sweepSnapshot{}, nil }
func (f *sweepFSM) Restore(io.ReadCloser) error    { return nil }

type sweepSnapshot struct{}

func (s *sweepSnapshot) Persist(SnapshotSink) error { return nil }
func (s *sweepSnapshot) Release()                  {}

func swEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func sweepAttempts(t *testing.T, name string, maxDelay time.Duration, attempts int) int {
	t.Helper()
	store := newSweepStore(maxDelay)
	snaps := NewInmemSnapshotStore()
	addr, trans := NewInmemTransport("S")
	trans.Connect(addr, trans)

	conf := DefaultConfig()
	conf.LocalID = "S"
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.ElectionTimeout = 30 * time.Second
	conf.HeartbeatTimeout = 30 * time.Second
	conf.LeaderLeaseTimeout = 30 * time.Second
	conf.CommitTimeout = time.Second

	cfg := Configuration{Servers: []Server{
		{Suffrage: Voter, ID: "S", Address: addr},
		{Suffrage: Voter, ID: "A", Address: "A"},
		{Suffrage: Voter, ID: "B", Address: "B"},
	}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, cfg); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, &sweepFSM{}, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("new raft: %v", err)
	}
	defer func() { _ = r.Shutdown().Error() }()
	leader := trans.EncodePeer("A", "A")

	inversions := 0
	for i := 0; i < attempts; i++ {
		cur := r.CurrentTerm()
		last := r.LastIndex()

		hbDone := make(chan struct{})
		go func(term uint64) {
			defer close(hbDone)
			rpc := RPC{Command: &AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: term, Leader: leader},
				RespChan: make(chan RPCResponse, 1)}
			r.processHeartbeat(rpc)
		}(cur + 1)

		req := &AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: cur + 2, Leader: leader,
			PrevLogEntry: last, LeaderCommitIndex: last + 1,
			Entries: []*Log{{Index: last + 1, Term: cur + 2, Type: LogCommand, Data: []byte("x")}}}
		if last == 0 {
			req.PrevLogTerm = 0
		} else {
			var prev Log
			if err := r.logs.GetLog(last, &prev); err == nil {
				req.PrevLogTerm = prev.Term
			}
		}
		resp := &AppendEntriesResponse{}
		if err := trans.AppendEntries("A", addr, req, resp); err != nil {
			t.Fatalf("appendEntries: %v", err)
		}
		<-hbDone

		if r.CurrentTerm() < cur+2 {
			inversions++
		}
		time.Sleep(time.Millisecond)
	}

	swEmit(t, map[string]interface{}{
		"event":        "sw_case_" + name,
		"case":         name,
		"attempts":     attempts,
		"max_delay_us": int(maxDelay / time.Microsecond),
	})
	swEmit(t, map[string]interface{}{
		"event":           "sw_result_" + name,
		"case":            name,
		"attempts":        attempts,
		"max_delay_us":    int(maxDelay / time.Microsecond),
		"inversion_count": inversions,
	})
	return inversions
}

func TestAssuranceHeartbeatDelaySweep(t *testing.T) {
	t.Run("delay_0us", func(t *testing.T) {
		sweepAttempts(t, "delay_0us", 0, 200)
	})
	t.Run("delay_250us", func(t *testing.T) {
		sweepAttempts(t, "delay_250us", 250*time.Microsecond, 200)
	})
	t.Run("delay_500us", func(t *testing.T) {
		sweepAttempts(t, "delay_500us", 500*time.Microsecond, 200)
	})
	t.Run("delay_1000us", func(t *testing.T) {
		sweepAttempts(t, "delay_1000us", time.Millisecond, 200)
	})
	t.Run("delay_2000us", func(t *testing.T) {
		sweepAttempts(t, "delay_2000us", 2*time.Millisecond, 200)
	})
}

package raft

// Construction notes:
//   * Four real members are bootstrapped, one non-leader member is demoted, so
//     the configuration has three voters and exactly one non-voter.
//   * The trigger cuts the leader from the two other voters and leaves the single
//     non-voter reachable, so the voter quorum is 2 and only the leader itself
//     can answer for the voters.
//   * The control cuts the non-voter as well, leaving no possible supporter.
//   * Earlier receipts used five members with two non-voters; this one tests
//     whether a single non-voter is enough for the same false success.

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func vxEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func vxRun(t *testing.T, name string, cutNonvoter bool) {
	t.Helper()
	conf := inmemConfig(t)
	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 4, Bootstrap: true, Conf: conf})
	defer c.Close()

	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader")
	}
	var others []*Raft
	for _, r := range c.rafts {
		if r != leader {
			others = append(others, r)
		}
	}
	if len(others) != 3 {
		t.Fatalf("expected three non-leader members, got %d", len(others))
	}
	nonvoter := others[0]
	if err := leader.DemoteVoter(nonvoter.localID, 0, 5*time.Second).Error(); err != nil {
		t.Fatalf("demote: %v", err)
	}
	// Wait until the demoted member's own view reports the new role.
	converged := false
	convergeStart := time.Now()
	for time.Since(convergeStart) < 2*time.Second {
		fut := nonvoter.GetConfiguration()
		if err := fut.Error(); err == nil {
			for _, srv := range fut.Configuration().Servers {
				if srv.ID == nonvoter.localID && srv.Suffrage != Voter {
					converged = true
				}
			}
		}
		if converged {
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	convergeMS := int(time.Since(convergeStart) / time.Millisecond)

	leaderTrans := leader.trans.(*InmemTransport)
	for _, r := range others[1:] {
		leaderTrans.Disconnect(r.localAddr)
		r.trans.(*InmemTransport).Disconnect(leader.localAddr)
	}
	if cutNonvoter {
		leaderTrans.Disconnect(nonvoter.localAddr)
		nonvoter.trans.(*InmemTransport).Disconnect(leader.localAddr)
	}

	vxEmit(t, map[string]interface{}{
		"event":               "vx_case_" + name,
		"case":                name,
		"members":             4,
		"voters":              3,
		"nonvoters":           1,
		"voters_reachable":    1,
		"nonvoters_reachable": map[bool]int{true: 0, false: 1}[cutNonvoter],
		"quorum_voters":       2,
		"demotion_converged":  converged,
		"demotion_converge_ms": convergeMS,
	})

	fut := leader.VerifyLeader()
	done := make(chan error, 1)
	start := time.Now()
	go func() { done <- fut.Error() }()
	verifyOK := false
	verifyErr := ""
	completed := false
	select {
	case err := <-done:
		completed = true
		if err != nil {
			verifyErr = err.Error()
		} else {
			verifyOK = true
		}
	case <-time.After(2 * time.Second):
		verifyErr = "no completion within two seconds"
	}
	vxEmit(t, map[string]interface{}{
		"event":          "vx_result_" + name,
		"case":           name,
		"completed":      completed,
		"verify_ok":      verifyOK,
		"verify_error":   verifyErr,
		"elapsed_ms":     int(time.Since(start) / time.Millisecond),
		"state_after":    leader.State().String(),
	})
	t.Logf("case=%s verifyOK=%v err=%q state=%s", name, verifyOK, verifyErr, leader.State())
}

func TestAssuranceVerifySingleNonvoter(t *testing.T) {
	t.Run("trigger_one_nonvoter_connected", func(t *testing.T) {
		vxRun(t, "trigger_one_nonvoter_connected", false)
	})
	t.Run("control_all_cut", func(t *testing.T) {
		vxRun(t, "control_all_cut", true)
	})
}

package raft

// Construction notes:
//   * Each attempt builds a fresh four-voter cluster, picks the leader and one
//     follower, starts DemoteVoter for that follower on a goroutine, and issues
//     LeadershipTransferToServer for the same member immediately afterwards,
//     without waiting for the demotion to commit or for any voter to apply it.
//   * The question is whether the transfer can install a member as leader while
//     the configuration change that removes its vote is still in flight.
//   * Every attempt records the demotion and transfer futures, whether the target
//     ever reported Leader, and the target's own role at the end.

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func cvEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

type cvOutcome struct {
	demoteOK        bool
	transferOK      bool
	transferErr     string
	targetEverLeader bool
	finalIsTarget   bool
	endRole         string
}

func cvAttempt(t *testing.T) cvOutcome {
	t.Helper()
	conf := inmemConfig(t)
	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 4, Bootstrap: true, Conf: conf})
	defer c.Close()

	out := cvOutcome{}
	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader")
	}
	var target *Raft
	for _, r := range c.rafts {
		if r != leader {
			target = r
			break
		}
	}
	if target == nil {
		t.Fatalf("no follower")
	}
	targetID := target.localID
	targetAddr := target.localAddr

	demoteDone := make(chan error, 1)
	go func() { demoteDone <- leader.DemoteVoter(targetID, 0, 5*time.Second).Error() }()

	transferLeader := c.Leader()
	if transferLeader == nil {
		out.transferErr = "no leader at transfer time"
		<-demoteDone
		return out
	}
	transferDone := make(chan error, 1)
	go func() { transferDone <- transferLeader.LeadershipTransferToServer(targetID, targetAddr).Error() }()

	select {
	case err := <-demoteDone:
		out.demoteOK = err == nil
	case <-time.After(5 * time.Second):
	}
	select {
	case err := <-transferDone:
		if err != nil {
			out.transferErr = err.Error()
		} else {
			out.transferOK = true
		}
	case <-time.After(3 * time.Second):
		out.transferErr = "no completion within three seconds"
	}

	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		if target.State() == Leader {
			out.targetEverLeader = true
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	if l := c.Leader(); l != nil {
		out.finalIsTarget = l.localID == targetID
	}
	if fut := target.GetConfiguration(); fut.Error() == nil {
		for _, srv := range fut.Configuration().Servers {
			if srv.ID == targetID {
				if srv.Suffrage == Voter {
					out.endRole = "voter"
				} else {
					out.endRole = "nonvoter"
				}
			}
		}
	}
	return out
}

func TestAssuranceTransferDemotionRace(t *testing.T) {
	const attempts = 20
	cvEmit(t, map[string]interface{}{
		"event":    "cv_case_demotion_race",
		"case":     "demotion_race",
		"attempts": attempts,
		"members":  4,
	})
	demoteOK, transferOK, targetLed, finalTarget, endNonvoter := 0, 0, 0, 0, 0
	lastErr := ""
	for i := 0; i < attempts; i++ {
		out := cvAttempt(t)
		if out.demoteOK {
			demoteOK++
		}
		if out.transferOK {
			transferOK++
		}
		if out.targetEverLeader {
			targetLed++
		}
		if out.finalIsTarget {
			finalTarget++
		}
		if out.endRole == "nonvoter" {
			endNonvoter++
		}
		if out.transferErr != "" {
			lastErr = out.transferErr
		}
	}
	cvEmit(t, map[string]interface{}{
		"event":                   "cv_result_demotion_race",
		"case":                    "demotion_race",
		"attempts":                attempts,
		"demote_ok_count":         demoteOK,
		"transfer_ok_count":       transferOK,
		"target_led_count":        targetLed,
		"final_target_count":      finalTarget,
		"target_ended_nonvoter":   endNonvoter,
		"last_transfer_error":     lastErr,
	})
	t.Logf("attempts=%d demoteOK=%d transferOK=%d targetLed=%d finalTarget=%d endNonvoter=%d lastErr=%q",
		attempts, demoteOK, transferOK, targetLed, finalTarget, endNonvoter, lastErr)
}

