		"last_log_index_after_fail": lastLogL,
		"phantom_voters":            len(latestServers),
		"phantom_servers":           fmt.Sprintf("%v", latestServers),
	})

	// Cut the leader from the other committed voter; optionally cut C as well.
	transL.Disconnect(addrP)
	transP.Disconnect(addrL)
	if cutNew {
		transL.Disconnect(addrC)
		transC.Disconnect(addrL)
	}

	deadline = time.Now().Add(10 * time.Second)
	for rL.State() != Leader && time.Now().Before(deadline) {
		time.Sleep(10 * time.Millisecond)
	}
	reElected := rL.State() == Leader
	applyErr := rL.Apply([]byte("grown-phantom"), 3*time.Second).Error()
	commitL := rL.CommitIndex()
	lastL, _ := stL.LastIndex()
	lastP, _ := stP.LastIndex()
	lastC, _ := storeC.LastIndex()
	pgEmit(t, map[string]interface{}{
		"event":                         "pg_result_" + caseName,
		"case":                          caseName,
		"add_failed":                    errAdd != nil,
		"cut_new_server":                cutNew,
		"latest_index_exceeds_log":      latestIndex > lastLogL,
		"re_elected":                    reElected,
		"apply_ok":                      applyErr == nil,
		"commit_index":                  commitL,
		"leader_last_index":             lastL,
		"committed_peer_last_index":     lastP,
		"new_server_last_index":         lastC,
		"committed_peer_has_entry":      lastP >= commitL,
		"new_server_has_entry":          lastC >= commitL,
		"commit_without_committed_voter": applyErr == nil && lastP < commitL,
	})
	t.Logf("case=%v reElected=%v applyErr=%v commitL=%d lastL=%d lastP=%d lastC=%d",
		caseName, reElected, applyErr, commitL, lastL, lastP, lastC)
}

func TestAssurancePhantomGrownQuorum(t *testing.T) {
	t.Run("grow_reachable_new_server", func(t *testing.T) {
		pgRun(t, "grow_reachable_new_server", false)
	})
	t.Run("grow_cut_new_server", func(t *testing.T) {
		pgRun(t, "grow_cut_new_server", true)
	})
}

harness.source:
package raft

// Construction notes:
//   * Five real nodes over in-memory transports: voters A, B, C and non-voters
//     D, E, all bootstrapped with the same configuration and a recording FSM.
//   * The leader writes "v1" and every node applies it. The leader is then
//     partitioned from the two other voters and keeps only the non-voters
//     reachable, so the committed voter quorum cannot answer it.
//   * Immediately after the partition the old leader is asked to verify itself,
//     which is the check a caller performs before serving a read. The trigger
//     keeps the non-voters reachable; the control also cuts them, leaving the old
//     leader with no possible supporter.
//   * The two remaining voters then elect a new leader and commit "v2". Once that
//     has happened the old leader is asked to verify itself again and its state
//     machine is read.
//   * The decisive observation is whether verification can still succeed after
//     the majority has moved on, which is what a stale verified read needs.

import (
	"encoding/json"
	"fmt"
	"io"
	"sync"
	"testing"
	"time"
)

func srEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

type srFSM struct {
	mu   sync.Mutex
	vals []string
}

func (f *srFSM) Apply(l *Log) interface{} {
	f.mu.Lock()
	f.vals = append(f.vals, string(l.Data))
	f.mu.Unlock()
	return nil
}

func (f *srFSM) last() string {
	f.mu.Lock()
	defer f.mu.Unlock()
	if len(f.vals) == 0 {
		return ""
	}
	return f.vals[len(f.vals)-1]
}

func (f *srFSM) Snapshot() (FSMSnapshot, error) { return &srSnap{}, nil }
func (f *srFSM) Restore(io.ReadCloser) error    { return nil }

type srSnap struct{}

func (s *srSnap) Persist(SnapshotSink) error { return nil }
func (s *srSnap) Release()                   {}

func srWaitLeader(t *testing.T, nodes []*Raft, want *Raft, timeout time.Duration) *Raft {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		for _, r := range nodes {
			if r == want {
				continue
			}
			if st := r.State(); st == Leader {
				return r
			}
		}
		time.Sleep(20 * time.Millisecond)
	}
	return nil
}

func srVerify(r *Raft, timeout time.Duration) (bool, string, bool) {
	done := make(chan error, 1)
	go func() { done <- r.VerifyLeader().Error() }()
	select {
	case err := <-done:
		if err != nil {
			return false, err.Error(), true
		}
		return true, "", true
	case <-time.After(timeout):
		return false, "no completion", false
	}
}

func srRun(t *testing.T, caseName string, cutNonvoters bool) {
	base := inmemConfig(t)
	// The lease may not exceed the heartbeat timeout. All members share a
	// one-second heartbeat and lease; the voters' election timeouts are staggered
	// so that, whichever member leads, the two remaining voters do not campaign in
	// lockstep and split the vote after the partition.
	base.HeartbeatTimeout = time.Second
	base.LeaderLeaseTimeout = time.Second
	electionTimeouts := map[string]time.Duration{
		"A": 1100 * time.Millisecond,
		"B": 2 * time.Second,
		"C": 3 * time.Second,
		"D": 3 * time.Second,
		"E": 3 * time.Second,
	}

	ids := []string{"A", "B", "C", "D", "E"}
	addrs := make(map[string]ServerAddress, len(ids))
	trans := make(map[string]*InmemTransport, len(ids))
	for _, id := range ids {
		a, tr := NewInmemTransport(ServerAddress(id))
		addrs[id] = a
		trans[id] = tr
	}
	for _, i := range ids {
		for _, j := range ids {
			if i != j {
				trans[i].Connect(addrs[j], trans[j])
			}
		}
	}

	servers := []Server{
		{Suffrage: Voter, ID: "A", Address: addrs["A"]},
		{Suffrage: Voter, ID: "B", Address: addrs["B"]},
		{Suffrage: Voter, ID: "C", Address: addrs["C"]},
		{Suffrage: Nonvoter, ID: "D", Address: addrs["D"]},
		{Suffrage: Nonvoter, ID: "E", Address: addrs["E"]},
	}
	cfg := Configuration{Servers: servers}

	nodes := make(map[string]*Raft, len(ids))
	fsms := make(map[string]*srFSM, len(ids))
	stores := make(map[string]*InmemStore, len(ids))
	snaps := make(map[string]*InmemSnapshotStore, len(ids))
	for _, id := range ids {
		conf := *base
		conf.LocalID = ServerID(id)
		conf.ElectionTimeout = electionTimeouts[id]
		store := NewInmemStore()
		snap := NewInmemSnapshotStore()
		if err := BootstrapCluster(&conf, store, store, snap, trans[id], cfg); err != nil {
			t.Fatalf("bootstrap %s: %v", id, err)
		}
		fsm := &srFSM{}
		r, err := NewRaft(&conf, fsm, store, store, snap, trans[id])
		if err != nil {
			t.Fatalf("raft %s: %v", id, err)
		}
		defer func(r *Raft) { _ = r.Shutdown().Error() }(r)
		nodes[id] = r
		fsms[id] = fsm
		stores[id] = store
		snaps[id] = snap
	}

	all := []*Raft{nodes["A"], nodes["B"], nodes["C"], nodes["D"], nodes["E"]}
	leader := srWaitLeader(t, all, nil, 10*time.Second)
	if leader == nil {
		t.Fatalf("no leader formed")
	}
	leaderID := string(leader.localID)

	if err := leader.Apply([]byte("v1"), 3*time.Second).Error(); err != nil {
		t.Fatalf("initial apply: %v", err)
	}
	time.Sleep(300 * time.Millisecond)

	// Partition the leader from the other two voters, and optionally from the
	// non-voters as well.
	leaderTrans := trans[leaderID]
	for _, id := range ids {
		if id == leaderID {
			continue
		}
		isVoter := id == "A" || id == "B" || id == "C"
		// Always cut the other voters; in the control, cut the non-voters too.
		if isVoter || cutNonvoters {
			leaderTrans.Disconnect(addrs[id])
			trans[id].Disconnect(addrs[leaderID])
		}
	}

	srEmit(t, map[string]interface{}{
		"event":               "sr_case_" + caseName,
		"case":                caseName,
		"members":             5,
		"voters":              3,
		"nonvoters":           2,
		"leader":              leaderID,
		"voters_reachable":    1,
		"nonvoters_reachable": map[bool]int{true: 0, false: 2}[cutNonvoters],
		"initial_value":       "v1",
		"leader_value":        fsms[leaderID].last(),
	})

	// While the old leader still believes it leads: verify, then write.
	cutAt := time.Now()
	verifyOK, verifyErr, verifyCompleted := srVerify(leader, 2*time.Second)
	msToVerify := int(time.Since(cutAt) / time.Millisecond)

	// The majority side elects a new leader and commits a different value.
	newLeader := srWaitLeader(t, all, leader, 12*time.Second)
	newLeaderID := ""
	newApplyOK := false
	newValue := ""
	if newLeader != nil {
		newLeaderID = string(newLeader.localID)
		newApplyOK = newLeader.Apply([]byte("v2"), 3*time.Second).Error() == nil
		time.Sleep(300 * time.Millisecond)
		newValue = fsms[newLeaderID].last()
	}
	msToNewLeader := -1
	if newLeaderID != "" {
		msToNewLeader = int(time.Since(cutAt) / time.Millisecond)
	}

	// Can the old leader still verify itself now that the majority has a leader?
	verifyAfterOK, verifyAfterErr, _ := srVerify(leader, 2*time.Second)
	oldValueBeforeHeal := fsms[leaderID].last()

	// Heal the partition and let the new leader's log reach the old one.
	for _, id := range ids {
		if id == leaderID {
			continue
		}
		leaderTrans.Connect(addrs[id], trans[id])
		trans[id].Connect(addrs[leaderID], leaderTrans)
	}
	time.Sleep(1500 * time.Millisecond)

	oldValue := fsms[leaderID].last()
	srEmit(t, map[string]interface{}{
		"event":             "sr_result_" + caseName,
		"case":              caseName,
		"old_leader":        leaderID,
		"old_leader_state":  leader.State().String(),
		"verify_completed":  verifyCompleted,
		"verify_after_partition_ok": verifyOK,
		"verify_error":      verifyErr,
		"ms_to_verify":      msToVerify,
		"new_leader":        newLeaderID,
		"new_apply_ok":      newApplyOK,
		"ms_to_new_leader":  msToNewLeader,
		"new_leader_value":  newValue,
		"verify_after_failover_ok": verifyAfterOK,
		"verify_after_failover_error": verifyAfterErr,
		"old_value_before_heal": oldValueBeforeHeal,
		"old_leader_value":  oldValue,
		"stale_verified_read": verifyAfterOK && newValue != "" && oldValueBeforeHeal != newValue,
	})
	t.Logf("case=%v old=%v verifyBefore=%v ms=%d newLeader=%v msNew=%d verifyAfter=%v errAfter=%q oldBeforeHeal=%q newValue=%q",
		caseName, leaderID, verifyOK, msToVerify, newLeaderID, msToNewLeader, verifyAfterOK, verifyAfterErr, oldValueBeforeHeal, newValue)
}

func TestAssuranceVerifyStaleRead(t *testing.T) {
	t.Run("trigger_nonvoters_connected", func(t *testing.T) {
		srRun(t, "trigger_nonvoters_connected", false)
	})
	t.Run("control_all_cut", func(t *testing.T) {
		srRun(t, "control_all_cut", true)
	})
}

package raft

// Construction notes:
//   * The startup replay pushes one commitTuple per MaxAppendEntries entries into
//     r.fsmMutateCh, whose capacity is fixed at 128 in the captured code, and the
//     only consumer is started after NewRaft returns.
//   * Earlier work measured the boundary at MaxAppendEntries=64 (8192 entries)
//     and MaxAppendEntries=1024 (131072 entries). This harness moves the batch
//     size to its smallest legal value, 1, so the predicted boundary is 128
//     entries rather than 8192.
//   * Cases: exactly 128 replayed entries, which is 128 batches and should
//     return, and 129 entries, which is 129 batches and should not.

import (
	"encoding/json"
	"fmt"
	"io"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

const rbBatchCapacity = 128

type rbFSM struct {
	mu      sync.Mutex
	applied int
}

func (f *rbFSM) Apply(*Log) interface{} {
	f.mu.Lock()
	f.applied++
	f.mu.Unlock()
	return nil
}

func (f *rbFSM) Snapshot() (FSMSnapshot, error) { return &rbSnapshot{}, nil }

func (f *rbFSM) Restore(io.ReadCloser) error {
	f.mu.Lock()
	f.applied = 0
	f.mu.Unlock()
	return nil
}

func (f *rbFSM) count() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.applied
}

type rbSnapshot struct{}

func (s *rbSnapshot) Persist(SnapshotSink) error { return nil }
func (s *rbSnapshot) Release()                  {}

func rbEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func rbConfig(id string) *Config {
	conf := DefaultConfig()
	conf.LocalID = ServerID(id)
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.HeartbeatTimeout = 50 * time.Millisecond
	conf.ElectionTimeout = 50 * time.Millisecond
	conf.LeaderLeaseTimeout = 50 * time.Millisecond
	conf.CommitTimeout = 5 * time.Millisecond
	conf.RestoreCommittedLogs = true
	conf.MaxAppendEntries = 1
	return conf
}

func rbBlockedProducers() int {
	buf := make([]byte, 1<<22)
	n := runtime.Stack(buf, true)
	return strings.Count(string(buf[:n]), "(*Raft).processLogs(")
}

type rbResult struct {
	returned    bool
	elapsed     time.Duration
	err         string
	applied     int
	blockedDiff int
}

func rbStart(conf *Config, fsm *rbFSM, store *InmemCommitTrackingStore,
	snaps SnapshotStore, addr ServerAddress, timeout time.Duration) rbResult {
	base := rbBlockedProducers()
	_, trans := NewInmemTransport(addr)
	done := make(chan error, 1)
	var raft *Raft
	start := time.Now()
	go func() {
		var err error
		raft, err = NewRaft(conf, fsm, store, store, snaps, trans)
		done <- err
	}()
	var res rbResult
	select {
	case err := <-done:
		res.returned = true
		res.elapsed = time.Since(start)
		if err != nil {
			res.err = err.Error()
		} else {
			defer func() { _ = raft.Shutdown().Error() }()
		}
	case <-time.After(timeout):
		res.elapsed = time.Since(start)
		res.err = "no return within observation window"
	}
	res.applied = fsm.count()
	res.blockedDiff = rbBlockedProducers() - base
	return res
}

func rbRun(t *testing.T, name string, entries uint64, timeout time.Duration) {
	store := NewInmemCommitTrackingStore()
	logs := make([]*Log, 0, entries)
	for i := uint64(1); i <= entries; i++ {
		logs = append(logs, &Log{Index: i, Term: 1, Type: LogCommand, Data: []byte("x")})
	}
	if err := store.StoreLogs(logs); err != nil {
		t.Fatalf("seed logs: %v", err)
	}
	if err := store.StageCommitIndex(entries); err != nil {
		t.Fatalf("stage commit index: %v", err)
	}
	lastLog, err := store.LastIndex()
	if err != nil {
		t.Fatalf("last index: %v", err)
	}
	rbEmit(t, map[string]interface{}{
		"event":                  "rb_case_" + name,
		"case":                   name,
		"mode":                   "seeded_commit_tracking_store",
		"restore_committed_logs": true,
		"max_append_entries":     1,
		"fsm_batch_capacity":     rbBatchCapacity,
		"entries":                entries,
		"staged_commit_index":    entries,
		"last_log_index":         lastLog,
		"replay_entries":         entries,
		"replay_batches":         entries,
		"timeout_ms":             int(timeout / time.Millisecond),
	})
	res := rbStart(rbConfig("node1"), &rbFSM{}, store, NewInmemSnapshotStore(), "node1", timeout)
	rbEmit(t, map[string]interface{}{
		"event":                          "rb_result_" + name,
		"case":                           name,
		"returned":                       res.returned,
		"elapsed_ms":                     int(res.elapsed / time.Millisecond),
		"error":                          res.err,
		"fsm_applied_sampled":            res.applied,
		"new_goroutines_in_process_logs": res.blockedDiff,
	})
	t.Logf("case=%s entries=%d returned=%v elapsed=%v err=%q", name, entries, res.returned, res.elapsed, res.err)
}

func TestAssuranceRestoreBatchOne(t *testing.T) {
	t.Run("control_128_batches_at_1", func(t *testing.T) {
		rbRun(t, "control_128_batches_at_1", 128, 10*time.Second)
	})
	t.Run("trigger_129_batches_at_1", func(t *testing.T) {
		rbRun(t, "trigger_129_batches_at_1", 129, 5*time.Second)
	})
}

package raft

// Construction notes:
//   * A real single-node cluster commits a first batch, takes a snapshot, then
//     commits a second batch, and is shut down. On restart the replay is the gap
//     between the snapshot index and the staged commit index, so the snapshot
//     shortens the replay instead of eliminating it.
//   * Short case: the second batch is small enough that the gap needs a handful
//     of FSM batches, which is the recovery region earlier work could only infer.
//   * Long case: the second batch pushes the gap past 128 batches at the default
//     MaxAppendEntries=64, which must block NewRaft.

import (
	"encoding/json"
	"fmt"
	"io"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

// Values taken from DefaultConfig(); recorded in every event so the boundary
// arithmetic stays inspectable.
const (
	rcMaxAppendEntries = 64
	rcBatchCapacity    = 128
)

type rcFSM struct {
	mu      sync.Mutex
	applied int
}

func (f *rcFSM) Apply(*Log) interface{} {
	f.mu.Lock()
	f.applied++
	f.mu.Unlock()
	return nil
}

func (f *rcFSM) Snapshot() (FSMSnapshot, error) { return &rcSnapshot{}, nil }

func (f *rcFSM) Restore(io.ReadCloser) error {
	f.mu.Lock()
	f.applied = 0
	f.mu.Unlock()
	return nil
}

func (f *rcFSM) count() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.applied
}

type rcSnapshot struct{}

func (s *rcSnapshot) Persist(SnapshotSink) error { return nil }
func (s *rcSnapshot) Release()                  {}

func rcEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func rcConfig(id string) *Config {
	conf := DefaultConfig()
	conf.LocalID = ServerID(id)
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.HeartbeatTimeout = 50 * time.Millisecond
	conf.ElectionTimeout = 50 * time.Millisecond
	conf.LeaderLeaseTimeout = 50 * time.Millisecond
	conf.CommitTimeout = 5 * time.Millisecond
	conf.RestoreCommittedLogs = true
	return conf
}

func rcBlockedProducers() int {
	buf := make([]byte, 1<<22)
	n := runtime.Stack(buf, true)
	return strings.Count(string(buf[:n]), "(*Raft).processLogs(")
}

type rcPrefix struct {
	store         *InmemCommitTrackingStore
	snaps         *InmemSnapshotStore
	stagedCommit  uint64
	lastLog       uint64
	snapshotIndex uint64
}

func rcBuildPrefix(t *testing.T, firstBatch, secondBatch int) rcPrefix {
	store := NewInmemCommitTrackingStore()
	snaps := NewInmemSnapshotStore()
	conf := rcConfig("node1")
	_, trans := NewInmemTransport("node1")
	configuration := Configuration{Servers: []Server{{Suffrage: Voter, ID: "node1", Address: trans.LocalAddr()}}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, &rcFSM{}, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("create producing raft: %v", err)
	}
	deadline := time.Now().Add(10 * time.Second)
	for r.Leader() == "" && time.Now().Before(deadline) {
		time.Sleep(2 * time.Millisecond)
	}
	if r.Leader() == "" {
		t.Fatalf("producing raft did not elect a leader")
	}
	apply := func(n int) {
		var last ApplyFuture
		for i := 0; i < n; i++ {
			last = r.Apply([]byte("x"), 5*time.Second)
		}
		if err := last.Error(); err != nil {
			t.Fatalf("apply: %v", err)
		}
	}
	apply(firstBatch)
	if err := r.Snapshot().Error(); err != nil {
		t.Fatalf("snapshot: %v", err)
	}
	apply(secondBatch)
	snapshotIndex := uint64(0)
	listed, err := snaps.List()
	if err != nil {
		t.Fatalf("list snapshots: %v", err)
	}
	if len(listed) > 0 {
		snapshotIndex = listed[0].Index
	}
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown: %v", err)
	}
	staged, err := store.GetCommitIndex()
	if err != nil {
		t.Fatalf("staged commit: %v", err)
	}
	lastLog, err := store.LastIndex()
	if err != nil {
		t.Fatalf("last log: %v", err)
	}
	return rcPrefix{store: store, snaps: snaps, stagedCommit: staged, lastLog: lastLog, snapshotIndex: snapshotIndex}
}

func rcRun(t *testing.T, name string, firstBatch, secondBatch int, timeout time.Duration) {
	prefix := rcBuildPrefix(t, firstBatch, secondBatch)
	replay := uint64(0)
	if prefix.stagedCommit > prefix.snapshotIndex {
		replay = prefix.stagedCommit - prefix.snapshotIndex
	}
	batches := (replay + rcMaxAppendEntries - 1) / rcMaxAppendEntries
	rcEmit(t, map[string]interface{}{
		"event":               "rc_case_" + name,
		"case":                name,
		"mode":                "real_cluster_restart_with_mid_snapshot",
		"restore_committed_logs": true,
		"first_batch":         firstBatch,
		"second_batch":        secondBatch,
		"snapshot_index":      prefix.snapshotIndex,
		"staged_commit_index": prefix.stagedCommit,
		"last_log_index":      prefix.lastLog,
		"replay_entries":      replay,
		"replay_batches":      batches,
		"max_append_entries":  rcMaxAppendEntries,
		"fsm_batch_capacity":  rcBatchCapacity,
		"timeout_ms":          int(timeout / time.Millisecond),
	})
	base := rcBlockedProducers()
	conf := rcConfig("node1")
	_, trans := NewInmemTransport("node1")
	done := make(chan error, 1)
	var raft *Raft
	start := time.Now()
	go func() {
		var err error
		raft, err = NewRaft(conf, &rcFSM{}, prefix.store, prefix.store, prefix.snaps, trans)
		done <- err
	}()
	returned := false
	errText := ""
	select {
	case err := <-done:
		returned = true
		if err != nil {
			errText = err.Error()
		} else {
			defer func() { _ = raft.Shutdown().Error() }()
		}
	case <-time.After(timeout):
		errText = "no return within observation window"
	}
	elapsed := time.Since(start)
	blocked := rcBlockedProducers() - base
	rcEmit(t, map[string]interface{}{
		"event":                  "rc_result_" + name,
		"case":                   name,
		"mode":                   "real_cluster_restart_with_mid_snapshot",
		"first_batch":            firstBatch,
		"second_batch":           secondBatch,
		"snapshot_index":         prefix.snapshotIndex,
		"staged_commit_index":    prefix.stagedCommit,
		"last_log_index":         prefix.lastLog,
		"replay_entries":         replay,
		"replay_batches":         batches,
		"max_append_entries":     rcMaxAppendEntries,
		"fsm_batch_capacity":     rcBatchCapacity,
		"returned":               returned,
		"elapsed_ms":             int(elapsed / time.Millisecond),
		"error":                  errText,
		"new_goroutines_in_process_logs": blocked,
	})
	t.Logf("case=%s snapshot=%d staged=%d replay=%d batches=%d returned=%v err=%q",
		name, prefix.snapshotIndex, prefix.stagedCommit, replay, batches, returned, errText)
}

func TestAssuranceRestorePartialReplay(t *testing.T) {
	t.Run("control_short_replay_after_snapshot", func(t *testing.T) {
		rcRun(t, "control_short_replay_after_snapshot", 200, 200, 10*time.Second)
	})
	t.Run("trigger_long_replay_after_snapshot", func(t *testing.T) {
		rcRun(t, "trigger_long_replay_after_snapshot", 200, 8300, 5*time.Second)
	})
}

package raft

// Construction notes:
//   * Same follower setup and race as the two-point jitter probe, but the stable
//     store's current-term write is delayed by a uniform interval drawn from
//     [0, maxDelay), and the harness sweeps maxDelay instead of testing a single
//     value: 0, 250 us, 500 us, 1 ms and 2 ms, 200 attempts each.
//   * Each attempt issues one fast-path heartbeat carrying cur+1 concurrently
//     with a term cur+2 AppendEntries through the real consumer path, then
//     records whether the persisted term ended below cur+2.
//   * The point is the shape of the rate against store latency, which the
//     target's own divergence note ties to heartbeat concurrency.

import (
	"encoding/json"
	"fmt"
	"io"
	"math/rand"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

type sweepStore struct {
	*InmemStore
	mu       sync.Mutex
	maxDelay time.Duration
	rnd      *rand.Rand
}

func newSweepStore(maxDelay time.Duration) *sweepStore {
	return &sweepStore{InmemStore: NewInmemStore(), maxDelay: maxDelay, rnd: rand.New(rand.NewSource(11))}
}

func (s *sweepStore) SetUint64(key []byte, val uint64) error {
	if string(key) == string(keyCurrentTerm) && s.maxDelay > 0 {
		s.mu.Lock()
		d := time.Duration(s.rnd.Int63n(int64(s.maxDelay)))
		s.mu.Unlock()
		time.Sleep(d)
	}
	return s.InmemStore.SetUint64(key, val)
}

type sweepFSM struct{ mu sync.Mutex }

func (f *sweepFSM) Apply(*Log) interface{}         { return nil }
func (f *sweepFSM) Snapshot() (FSMSnapshot, error) { return &sweepSnapshot{}, nil }
func (f *sweepFSM) Restore(io.ReadCloser) error    { return nil }

type sweepSnapshot struct{}

func (s *sweepSnapshot) Persist(SnapshotSink) error { return nil }
func (s *sweepSnapshot) Release()                  {}

func swEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func sweepAttempts(t *testing.T, name string, maxDelay time.Duration, attempts int) int {
	t.Helper()
	store := newSweepStore(maxDelay)
	snaps := NewInmemSnapshotStore()
	addr, trans := NewInmemTransport("S")
	trans.Connect(addr, trans)

	conf := DefaultConfig()
	conf.LocalID = "S"
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.ElectionTimeout = 30 * time.Second
	conf.HeartbeatTimeout = 30 * time.Second
	conf.LeaderLeaseTimeout = 30 * time.Second
	conf.CommitTimeout = time.Second

	cfg := Configuration{Servers: []Server{
		{Suffrage: Voter, ID: "S", Address: addr},
		{Suffrage: Voter, ID: "A", Address: "A"},
		{Suffrage: Voter, ID: "B", Address: "B"},
	}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, cfg); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, &sweepFSM{}, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("new raft: %v", err)
	}
	defer func() { _ = r.Shutdown().Error() }()
	leader := trans.EncodePeer("A", "A")

	inversions := 0
	for i := 0; i < attempts; i++ {
		cur := r.CurrentTerm()
		last := r.LastIndex()

		hbDone := make(chan struct{})
		go func(term uint64) {
			defer close(hbDone)
			rpc := RPC{Command: &AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: term, Leader: leader},
				RespChan: make(chan RPCResponse, 1)}
			r.processHeartbeat(rpc)
		}(cur + 1)

		req := &AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: cur + 2, Leader: leader,
			PrevLogEntry: last, LeaderCommitIndex: last + 1,
			Entries: []*Log{{Index: last + 1, Term: cur + 2, Type: LogCommand, Data: []byte("x")}}}
		if last == 0 {
			req.PrevLogTerm = 0
		} else {
			var prev Log
			if err := r.logs.GetLog(last, &prev); err == nil {
				req.PrevLogTerm = prev.Term
			}
		}
		resp := &AppendEntriesResponse{}
		if err := trans.AppendEntries("A", addr, req, resp); err != nil {
			t.Fatalf("appendEntries: %v", err)
		}
		<-hbDone

		if r.CurrentTerm() < cur+2 {
			inversions++
		}
		time.Sleep(time.Millisecond)
	}

	swEmit(t, map[string]interface{}{
		"event":        "sw_case_" + name,
		"case":         name,
		"attempts":     attempts,
		"max_delay_us": int(maxDelay / time.Microsecond),
	})
	swEmit(t, map[string]interface{}{
		"event":           "sw_result_" + name,
		"case":            name,
		"attempts":        attempts,
		"max_delay_us":    int(maxDelay / time.Microsecond),
		"inversion_count": inversions,
	})
	return inversions
}

func TestAssuranceHeartbeatDelaySweep(t *testing.T) {
	t.Run("delay_0us", func(t *testing.T) {
		sweepAttempts(t, "delay_0us", 0, 200)
	})
	t.Run("delay_250us", func(t *testing.T) {
		sweepAttempts(t, "delay_250us", 250*time.Microsecond, 200)
	})
	t.Run("delay_500us", func(t *testing.T) {
		sweepAttempts(t, "delay_500us", 500*time.Microsecond, 200)
	})
	t.Run("delay_1000us", func(t *testing.T) {
		sweepAttempts(t, "delay_1000us", time.Millisecond, 200)
	})
	t.Run("delay_2000us", func(t *testing.T) {
		sweepAttempts(t, "delay_2000us", 2*time.Millisecond, 200)
	})
}

package raft

// Construction notes:
//   * Four real members are bootstrapped, one non-leader member is demoted, so
//     the configuration has three voters and exactly one non-voter.
//   * The trigger cuts the leader from the two other voters and leaves the single
//     non-voter reachable, so the voter quorum is 2 and only the leader itself
//     can answer for the voters.
//   * The control cuts the non-voter as well, leaving no possible supporter.
//   * Earlier receipts used five members with two non-voters; this one tests
//     whether a single non-voter is enough for the same false success.

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func vxEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func vxRun(t *testing.T, name string, cutNonvoter bool) {
	t.Helper()
	conf := inmemConfig(t)
	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 4, Bootstrap: true, Conf: conf})
	defer c.Close()

	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader")
	}
	var others []*Raft
	for _, r := range c.rafts {
		if r != leader {
			others = append(others, r)
		}
	}
	if len(others) != 3 {
		t.Fatalf("expected three non-leader members, got %d", len(others))
	}
	nonvoter := others[0]
	if err := leader.DemoteVoter(nonvoter.localID, 0, 5*time.Second).Error(); err != nil {
		t.Fatalf("demote: %v", err)
	}
	// Wait until the demoted member's own view reports the new role.
	converged := false
	convergeStart := time.Now()
	for time.Since(convergeStart) < 2*time.Second {
		fut := nonvoter.GetConfiguration()
		if err := fut.Error(); err == nil {
			for _, srv := range fut.Configuration().Servers {
				if srv.ID == nonvoter.localID && srv.Suffrage != Voter {
					converged = true
				}
			}
		}
		if converged {
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	convergeMS := int(time.Since(convergeStart) / time.Millisecond)

	leaderTrans := leader.trans.(*InmemTransport)
	for _, r := range others[1:] {
		leaderTrans.Disconnect(r.localAddr)
		r.trans.(*InmemTransport).Disconnect(leader.localAddr)
	}
	if cutNonvoter {
		leaderTrans.Disconnect(nonvoter.localAddr)
		nonvoter.trans.(*InmemTransport).Disconnect(leader.localAddr)
	}

	vxEmit(t, map[string]interface{}{
		"event":               "vx_case_" + name,
		"case":                name,
		"members":             4,
		"voters":              3,
		"nonvoters":           1,
		"voters_reachable":    1,
		"nonvoters_reachable": map[bool]int{true: 0, false: 1}[cutNonvoter],
		"quorum_voters":       2,
		"demotion_converged":  converged,
		"demotion_converge_ms": convergeMS,
	})

	fut := leader.VerifyLeader()
	done := make(chan error, 1)
	start := time.Now()
	go func() { done <- fut.Error() }()
	verifyOK := false
	verifyErr := ""
	completed := false
	select {
	case err := <-done:
		completed = true
		if err != nil {
			verifyErr = err.Error()
		} else {
			verifyOK = true
		}
	case <-time.After(2 * time.Second):
		verifyErr = "no completion within two seconds"
	}
	vxEmit(t, map[string]interface{}{
		"event":          "vx_result_" + name,
		"case":           name,
		"completed":      completed,
		"verify_ok":      verifyOK,
		"verify_error":   verifyErr,
		"elapsed_ms":     int(time.Since(start) / time.Millisecond),
		"state_after":    leader.State().String(),
	})
	t.Logf("case=%s verifyOK=%v err=%q state=%s", name, verifyOK, verifyErr, leader.State())
}

func TestAssuranceVerifySingleNonvoter(t *testing.T) {
	t.Run("trigger_one_nonvoter_connected", func(t *testing.T) {
		vxRun(t, "trigger_one_nonvoter_connected", false)
	})
	t.Run("control_all_cut", func(t *testing.T) {
		vxRun(t, "control_all_cut", true)
	})
}

package raft

// Construction notes:
//   * Each attempt builds a fresh four-voter cluster, picks the leader and one
//     follower, starts DemoteVoter for that follower on a goroutine, and issues
//     LeadershipTransferToServer for the same member immediately afterwards,
//     without waiting for the demotion to commit or for any voter to apply it.
//   * The question is whether the transfer can install a member as leader while
//     the configuration change that removes its vote is still in flight.
//   * Every attempt records the demotion and transfer futures, whether the target
//     ever reported Leader, and the target's own role at the end.

import (
	"encoding/json"
	"fmt"
	"testing"
	"time"
)

func cvEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

type cvOutcome struct {
	demoteOK        bool
	transferOK      bool
	transferErr     string
	targetEverLeader bool
	finalIsTarget   bool
	endRole         string
}

func cvAttempt(t *testing.T) cvOutcome {
	t.Helper()
	conf := inmemConfig(t)
	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 4, Bootstrap: true, Conf: conf})
	defer c.Close()

	out := cvOutcome{}
	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader")
	}
	var target *Raft
	for _, r := range c.rafts {
		if r != leader {
			target = r
			break
		}
	}
	if target == nil {
		t.Fatalf("no follower")
	}
	targetID := target.localID
	targetAddr := target.localAddr

	demoteDone := make(chan error, 1)
	go func() { demoteDone <- leader.DemoteVoter(targetID, 0, 5*time.Second).Error() }()

	transferLeader := c.Leader()
	if transferLeader == nil {
		out.transferErr = "no leader at transfer time"
		<-demoteDone
		return out
	}
	transferDone := make(chan error, 1)
	go func() { transferDone <- transferLeader.LeadershipTransferToServer(targetID, targetAddr).Error() }()

	select {
	case err := <-demoteDone:
		out.demoteOK = err == nil
	case <-time.After(5 * time.Second):
	}
	select {
	case err := <-transferDone:
		if err != nil {
			out.transferErr = err.Error()
		} else {
			out.transferOK = true
		}
	case <-time.After(3 * time.Second):
		out.transferErr = "no completion within three seconds"
	}

	deadline := time.Now().Add(2 * time.Second)
	for time.Now().Before(deadline) {
		if target.State() == Leader {
			out.targetEverLeader = true
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	if l := c.Leader(); l != nil {
		out.finalIsTarget = l.localID == targetID
	}
	if fut := target.GetConfiguration(); fut.Error() == nil {
		for _, srv := range fut.Configuration().Servers {
			if srv.ID == targetID {
				if srv.Suffrage == Voter {
					out.endRole = "voter"
				} else {
					out.endRole = "nonvoter"
				}
			}
		}
	}
	return out
}

func TestAssuranceTransferDemotionRace(t *testing.T) {
	const attempts = 20
	cvEmit(t, map[string]interface{}{
		"event":    "cv_case_demotion_race",
		"case":     "demotion_race",
		"attempts": attempts,
		"members":  4,
	})
	demoteOK, transferOK, targetLed, finalTarget, endNonvoter := 0, 0, 0, 0, 0
	lastErr := ""
	for i := 0; i < attempts; i++ {
		out := cvAttempt(t)
		if out.demoteOK {
			demoteOK++
		}
		if out.transferOK {
			transferOK++
		}
		if out.targetEverLeader {
			targetLed++
		}
		if out.finalIsTarget {
			finalTarget++
		}
		if out.endRole == "nonvoter" {
			endNonvoter++
		}
		if out.transferErr != "" {
			lastErr = out.transferErr
		}
	}
	cvEmit(t, map[string]interface{}{
		"event":                   "cv_result_demotion_race",
		"case":                    "demotion_race",
		"attempts":                attempts,
		"demote_ok_count":         demoteOK,
		"transfer_ok_count":       transferOK,
		"target_led_count":        targetLed,
		"final_target_count":      finalTarget,
		"target_ended_nonvoter":   endNonvoter,
		"last_transfer_error":     lastErr,
	})
	t.Logf("attempts=%d demoteOK=%d transferOK=%d targetLed=%d finalTarget=%d endNonvoter=%d lastErr=%q",
		attempts, demoteOK, transferOK, targetLed, finalTarget, endNonvoter, lastErr)
}

package raft

// Construction notes:
//   * Earlier startup receipts observed the hanging replay for 5000 ms. This
//     harness keeps the default batch size and the exact boundary state, and
//     watches the 129-batch case for thirty seconds instead.
//   * The control replays 8192 entries (128 batches) with a ten-second window and
//     is expected to return in milliseconds, which shows that a thirty-second
//     wait is far longer than a completed replay of this size needs.

import (
	"encoding/json"
	"fmt"
	"io"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

type ppFSM struct {
	mu      sync.Mutex
	applied int
}

func (f *ppFSM) Apply(*Log) interface{} {
	f.mu.Lock()
	f.applied++
	f.mu.Unlock()
	return nil
}

func (f *ppFSM) Snapshot() (FSMSnapshot, error) { return &ppSnapshot{}, nil }

func (f *ppFSM) Restore(io.ReadCloser) error {
	f.mu.Lock()
	f.applied = 0
	f.mu.Unlock()
	return nil
}

type ppSnapshot struct{}

func (s *ppSnapshot) Persist(SnapshotSink) error { return nil }
func (s *ppSnapshot) Release()                  {}

func ppEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func ppConfig(id string) *Config {
	conf := DefaultConfig()
	conf.LocalID = ServerID(id)
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.HeartbeatTimeout = 50 * time.Millisecond
	conf.ElectionTimeout = 50 * time.Millisecond
	conf.LeaderLeaseTimeout = 50 * time.Millisecond
	conf.CommitTimeout = 5 * time.Millisecond
	conf.RestoreCommittedLogs = true
	return conf
}

func ppBlocked() int {
	buf := make([]byte, 1<<22)
	n := runtime.Stack(buf, true)
	return strings.Count(string(buf[:n]), "(*Raft).processLogs(")
}

func ppRun(t *testing.T, name string, entries uint64, window time.Duration) {
	store := NewInmemCommitTrackingStore()
	logs := make([]*Log, 0, entries)
	for i := uint64(1); i <= entries; i++ {
		logs = append(logs, &Log{Index: i, Term: 1, Type: LogCommand, Data: []byte("x")})
	}
	if err := store.StoreLogs(logs); err != nil {
		t.Fatalf("seed logs: %v", err)
	}
	if err := store.StageCommitIndex(entries); err != nil {
		t.Fatalf("stage commit index: %v", err)
	}
	_, trans := NewInmemTransport("P")
	fsm := &ppFSM{}
	base := ppBlocked()
	ppEmit(t, map[string]interface{}{
		"event":              "pp_case_" + name,
		"case":               name,
		"entries":            entries,
		"replay_batches":     (entries + 63) / 64,
		"max_append_entries": 64,
		"window_ms":          int(window / time.Millisecond),
		"restore_committed_logs": true,
	})
	done := make(chan error, 1)
	var raft *Raft
	start := time.Now()
	go func() {
		var err error
		raft, err = NewRaft(ppConfig("P"), fsm, store, store, NewInmemSnapshotStore(), trans)
		done <- err
	}()
	returned := false
	errText := ""
	select {
	case err := <-done:
		returned = true
		if err != nil {
			errText = err.Error()
		} else {
			defer func() { _ = raft.Shutdown().Error() }()
		}
	case <-time.After(window):
		errText = "no return within observation window"
	}
	ppEmit(t, map[string]interface{}{
		"event":               "pp_result_" + name,
		"case":                name,
		"returned":            returned,
		"elapsed_ms":          int(time.Since(start) / time.Millisecond),
		"error":               errText,
		"new_blocked_process": ppBlocked() - base,
	})
	t.Logf("case=%s entries=%d window=%v returned=%v", name, entries, window, returned)
}

func TestAssuranceStartupPermanence(t *testing.T) {
	t.Run("control_128_batches", func(t *testing.T) {
		ppRun(t, "control_128_batches", 8192, 10*time.Second)
	})
	t.Run("trigger_129_batches_30s", func(t *testing.T) {
		ppRun(t, "trigger_129_batches_30s", 8193, 30*time.Second)
	})
}

package raft

// Construction notes:
//   * Same follower race as the jitter probes, but the stable store performs a
//     real file write plus fsync for every current-term update instead of
//     sleeping for a synthetic delay.
//   * This tests whether the inversion appears under genuine disk latency
//     rather than under an injected sleep.
//   * The harness records the inversion count, the number of attempts, and the
//     mean and maximum duration of the term write so the latency actually
//     exercised is visible in the receipt.

import (
	"encoding/binary"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

type fsyncStore struct {
	*InmemStore
	mu       sync.Mutex
	file     *os.File
	total    time.Duration
	max      time.Duration
	writes   int
}

func newFsyncStore(dir string) (*fsyncStore, error) {
	f, err := os.Create(filepath.Join(dir, "term.bin"))
	if err != nil {
		return nil, err
	}
	return &fsyncStore{InmemStore: NewInmemStore(), file: f}, nil
}

func (s *fsyncStore) SetUint64(key []byte, val uint64) error {
	if string(key) == string(keyCurrentTerm) {
		var buf [8]byte
		binary.LittleEndian.PutUint64(buf[:], val)
		start := time.Now()
		if _, err := s.file.WriteAt(buf[:], 0); err != nil {
			return err
		}
		if err := s.file.Sync(); err != nil {
			return err
		}
		d := time.Since(start)
		s.mu.Lock()
		s.total += d
		s.writes++
		if d > s.max {
			s.max = d
		}
		s.mu.Unlock()
	}
	return s.InmemStore.SetUint64(key, val)
}

func (s *fsyncStore) stats() (time.Duration, time.Duration, int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.writes == 0 {
		return 0, 0, 0
	}
	return s.total / time.Duration(s.writes), s.max, s.writes
}

type fsFSM struct{ mu sync.Mutex }

func (f *fsFSM) Apply(*Log) interface{}         { return nil }
func (f *fsFSM) Snapshot() (FSMSnapshot, error) { return &fsSnapshot{}, nil }
func (f *fsFSM) Restore(io.ReadCloser) error    { return nil }

type fsSnapshot struct{}

func (s *fsSnapshot) Persist(SnapshotSink) error { return nil }
func (s *fsSnapshot) Release()                  {}

func fsEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func TestAssuranceHeartbeatFsync(t *testing.T) {
	const attempts = 200
	store, err := newFsyncStore(t.TempDir())
	if err != nil {
		t.Fatalf("store: %v", err)
	}
	snaps := NewInmemSnapshotStore()
	addr, trans := NewInmemTransport("F")
	trans.Connect(addr, trans)

	conf := DefaultConfig()
	conf.LocalID = "F"
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.ElectionTimeout = 30 * time.Second
	conf.HeartbeatTimeout = 30 * time.Second
	conf.LeaderLeaseTimeout = 30 * time.Second
	conf.CommitTimeout = time.Second

	cfg := Configuration{Servers: []Server{
		{Suffrage: Voter, ID: "F", Address: addr},
		{Suffrage: Voter, ID: "A", Address: "A"},
		{Suffrage: Voter, ID: "B", Address: "B"},
	}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, cfg); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, &fsFSM{}, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("new raft: %v", err)
	}
	defer func() { _ = r.Shutdown().Error() }()
	leader := trans.EncodePeer("A", "A")

	fsEmit(t, map[string]interface{}{
		"event":    "cd_case_fsync_term_writes",
		"case":     "fsync_term_writes",
		"attempts": attempts,
		"mode":     "file_write_plus_fsync",
	})

	inversions := 0
	for i := 0; i < attempts; i++ {
		cur := r.CurrentTerm()
		last := r.LastIndex()

		hbDone := make(chan struct{})
		go func(term uint64) {
			defer close(hbDone)
			rpc := RPC{Command: &AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: term, Leader: leader},
				RespChan: make(chan RPCResponse, 1)}
			r.processHeartbeat(rpc)
		}(cur + 1)

		req := &AppendEntriesRequest{RPCHeader: r.getRPCHeader(), Term: cur + 2, Leader: leader,
			PrevLogEntry: last, LeaderCommitIndex: last + 1,
			Entries: []*Log{{Index: last + 1, Term: cur + 2, Type: LogCommand, Data: []byte("x")}}}
		if last == 0 {
			req.PrevLogTerm = 0
		} else {
			var prev Log
			if err := r.logs.GetLog(last, &prev); err == nil {
				req.PrevLogTerm = prev.Term
			}
		}
		resp := &AppendEntriesResponse{}
		if err := trans.AppendEntries("A", addr, req, resp); err != nil {
			t.Fatalf("appendEntries: %v", err)
		}
		<-hbDone
		if r.CurrentTerm() < cur+2 {
			inversions++
		}
		time.Sleep(time.Millisecond)
	}
	mean, max, writes := store.stats()
	fsEmit(t, map[string]interface{}{
		"event":            "cd_result_fsync_term_writes",
		"case":             "fsync_term_writes",
		"attempts":         attempts,
		"inversion_count":  inversions,
		"term_writes":      writes,
		"mean_write_us":    int(mean / time.Microsecond),
		"max_write_us":     int(max / time.Microsecond),
	})
	t.Logf("attempts=%d inversions=%d writes=%d mean=%v max=%v", attempts, inversions, writes, mean, max)
}

package raft

// Construction notes:
//   * Each case runs a real single-node cluster that commits a first batch,
//     takes a snapshot, then commits a second batch, and shuts down, so the
//     restart replays only the tail after the snapshot.
//   * Three tails are measured at the default MaxAppendEntries of 64: about
//     fifty FSM batches, which is inside the range that earlier receipts only
//     covered with a seeded store state; exactly one hundred and twenty eight
//     batches, the channel capacity itself, measured on a large real tail so a
//     slow replay cannot be mistaken for a capacity effect; and one entry past
//     that, which the seeded boundary says must not return.

import (
	"encoding/json"
	"fmt"
	"io"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"

	hclog "github.com/hashicorp/go-hclog"
)

type mbFSM struct {
	mu      sync.Mutex
	applied int
}

func (f *mbFSM) Apply(*Log) interface{} {
	f.mu.Lock()
	f.applied++
	f.mu.Unlock()
	return nil
}

func (f *mbFSM) Snapshot() (FSMSnapshot, error) { return &mbSnapshot{}, nil }

func (f *mbFSM) Restore(io.ReadCloser) error {
	f.mu.Lock()
	f.applied = 0
	f.mu.Unlock()
	return nil
}

type mbSnapshot struct{}

func (s *mbSnapshot) Persist(SnapshotSink) error { return nil }
func (s *mbSnapshot) Release()                   {}

func mbEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func mbConfig(id string) *Config {
	conf := DefaultConfig()
	conf.LocalID = ServerID(id)
	conf.Logger = hclog.NewNullLogger()
	conf.LogLevel = "ERROR"
	conf.HeartbeatTimeout = 50 * time.Millisecond
	conf.ElectionTimeout = 50 * time.Millisecond
	conf.LeaderLeaseTimeout = 50 * time.Millisecond
	conf.CommitTimeout = 5 * time.Millisecond
	conf.RestoreCommittedLogs = true
	return conf
}

func mbBlocked() int {
	buf := make([]byte, 1<<22)
	n := runtime.Stack(buf, true)
	return strings.Count(string(buf[:n]), "(*Raft).processLogs(")
}

func TestAssuranceRestoreMidbandReplay(t *testing.T) {
	cases := []struct {
		name        string
		secondBatch int
		event       string
	}{
		{name: "midband_replay", secondBatch: 3200, event: "mb_case_midband_replay"},
		{name: "capacity_replay", secondBatch: 8194, event: "mb_case_capacity_replay"},
		{name: "over_capacity_replay", secondBatch: 8195, event: "mb_case_over_capacity_replay"},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			mbRunCase(t, tc.name, tc.event, tc.secondBatch)
		})
	}
}

func mbRunCase(t *testing.T, name string, caseEvent string, secondBatch int) {
	t.Helper()
	const firstBatch = 200
	const window = 20 * time.Second

	store := NewInmemCommitTrackingStore()
	snaps := NewInmemSnapshotStore()
	conf := mbConfig("node1")
	_, trans := NewInmemTransport("node1")
	configuration := Configuration{Servers: []Server{{Suffrage: Voter, ID: "node1", Address: trans.LocalAddr()}}}
	if err := BootstrapCluster(conf, store, store, snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap: %v", err)
	}
	r, err := NewRaft(conf, &mbFSM{}, store, store, snaps, trans)
	if err != nil {
		t.Fatalf("producing raft: %v", err)
	}
	deadline := time.Now().Add(10 * time.Second)
	for r.Leader() == "" && time.Now().Before(deadline) {
		time.Sleep(2 * time.Millisecond)
	}
	if r.Leader() == "" {
		t.Fatalf("no leader")
	}
	apply := func(n int) {
		var last ApplyFuture
		for i := 0; i < n; i++ {
			last = r.Apply([]byte("x"), 5*time.Second)
		}
		if err := last.Error(); err != nil {
			t.Fatalf("apply: %v", err)
		}
	}
	apply(firstBatch)
	if err := r.Snapshot().Error(); err != nil {
		t.Fatalf("snapshot: %v", err)
	}
	apply(secondBatch)
	snapshotIndex := uint64(0)
	listed, err := snaps.List()
	if err != nil {
		t.Fatalf("list snapshots: %v", err)
	}
	if len(listed) > 0 {
		snapshotIndex = listed[0].Index
	}
	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown: %v", err)
	}
	staged, err := store.GetCommitIndex()
	if err != nil {
		t.Fatalf("staged commit: %v", err)
	}
	lastLog, err := store.LastIndex()
	if err != nil {
		t.Fatalf("last log: %v", err)
	}
	replay := uint64(0)
	if staged > snapshotIndex {
		replay = staged - snapshotIndex
	}
	batches := (replay + 63) / 64

	mbEmit(t, map[string]interface{}{
		"event":                  caseEvent,
		"case":                   name,
		"mode":                   "real_cluster_restart_with_snapshot_bound_tail",
		"restore_committed_logs": true,
		"first_batch":            firstBatch,
		"second_batch":           secondBatch,
		"snapshot_index":         snapshotIndex,
		"staged_commit_index":    staged,
		"last_log_index":         lastLog,
		"replay_entries":         replay,
		"replay_batches":         batches,
		"max_append_entries":     64,
		"window_ms":              int(window / time.Millisecond),
	})

	base := mbBlocked()
	start := time.Now()
	done := make(chan error, 1)
	var restarted *Raft
	go func() {
		var rerr error
		restarted, rerr = NewRaft(mbConfig("node1"), &mbFSM{}, store, store, snaps, trans)
		done <- rerr
	}()
	returned := false
	errText := ""
	select {
	case err := <-done:
		returned = true
		if err != nil {
			errText = err.Error()
		} else {
			defer func() { _ = restarted.Shutdown().Error() }()
		}
	case <-time.After(window):
		errText = "no return within observation window"
	}
	mbEmit(t, map[string]interface{}{
		"event":               strings.Replace(caseEvent, "mb_case_", "mb_result_", 1),
		"case":                name,
		"returned":            returned,
		"elapsed_ms":          int(time.Since(start) / time.Millisecond),
		"error":               errText,
		"new_blocked_process": mbBlocked() - base,
	})
	t.Logf("case=%s replay=%d batches=%d returned=%v err=%q", name, replay, batches, returned, errText)
}

package raft

// Construction notes:
//   * One real four-member cluster is bootstrapped, one non-leader member is
//     demoted with DemoteVoter, and the harness waits until that member's own
//     configuration view reports the non-voter role.
//   * The control then calls LeadershipTransfer(), the automatic form that has no
//     target, and records whether a leader exists afterwards and whether it is a
//     voter.
//   * The trigger calls LeadershipTransferToServer for the demoted member and
//     records the future result, whether that member ever reports Leader, and the
//     sampled interval without a leader.
//   * The point of the pair is the asymmetry between the two entry points on the
//     same cluster state.

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
	"time"
)

func xgEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

func xgRun(t *testing.T, name string, explicit bool) {
	t.Helper()
	const sampleEvery = 10 * time.Millisecond
	const watchWindow = 3 * time.Second

	conf := inmemConfig(t)
	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 4, Bootstrap: true, Conf: conf})
	defer c.Close()

	// Choose the member to demote at the moment of the demotion, so the target is
	// definitely a follower then: demoting the sitting leader starts a transfer of
	// its own and would contaminate the case.
	leader := c.Leader()
	if leader == nil {
		t.Fatalf("no leader")
	}
	var target *Raft
	for _, r := range c.rafts {
		if r.localID != leader.localID {
			target = r
			break
		}
	}
	if target == nil {
		t.Fatalf("no non-leader peer")
	}
	targetID := target.localID
	demotedWasLeader := leader.localID == targetID

	if err := leader.DemoteVoter(targetID, 0, 5*time.Second).Error(); err != nil {
		t.Fatalf("demote: %v", err)
	}
	roleOf := func() string {
		fut := target.GetConfiguration()
		if err := fut.Error(); err != nil {
			return "unknown"
		}
		for _, srv := range fut.Configuration().Servers {
			if srv.ID == targetID {
				if srv.Suffrage == Voter {
					return "voter"
				}
				return "nonvoter"
			}
		}
		return "absent"
	}
	convergeStart := time.Now()
	converged := false
	for time.Since(convergeStart) < 2*time.Second {
		if roleOf() == "nonvoter" {
			converged = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	convergeMS := int(time.Since(convergeStart) / time.Millisecond)

	mode := "automatic"
	if explicit {
		mode = "explicit_to_demoted_member"
	}
	xgEmit(t, map[string]interface{}{
		"event":              "xg_case_" + name,
		"case":               name,
		"mode":               mode,
		"members":            4,
		"voters":             3,
		"nonvoters":          1,
		"demoted_member":     string(targetID),
		"role_view":          roleOf(),
		"converged":          converged,
		"converge_ms":        convergeMS,
		"leader_before":      string(leader.localID),
		"demoted_was_leader": demotedWasLeader,
	})

	futureOK := false
	futureErr := ""
	futureDone := false
	attempts := 0
	start := time.Now()
	attemptErrors := []string{}
	firstAttemptOK := false
	firstAttemptErr := ""
	for attempts < 5 {
		transferLeader := c.Leader()
		if transferLeader == nil {
			futureErr = "no leader at transfer time"
			attemptErrors = append(attemptErrors, futureErr)
			break
		}
		fut := transferLeader.LeadershipTransfer()
		if explicit {
			fut = transferLeader.LeadershipTransferToServer(targetID, target.localAddr)
		}
		attempts++
		done := make(chan error, 1)
		go func() { done <- fut.Error() }()
		var err error
		select {
		case err = <-done:
			futureDone = true
		case <-time.After(5 * time.Second):
			err = fmt.Errorf("no completion within five seconds")
		}
		attemptErrText := ""
		if err != nil {
			attemptErrText = err.Error()
		}
		attemptErrors = append(attemptErrors, attemptErrText)
		if attempts == 1 {
			firstAttemptOK = err == nil
			firstAttemptErr = attemptErrText
		}
		if err == nil {
			futureOK = true
			futureErr = ""
			break
		}
		futureErr = err.Error()
		if !strings.Contains(futureErr, "in progress") {
			break
		}
		time.Sleep(100 * time.Millisecond)
	}
	futureMS := int(time.Since(start) / time.Millisecond)

	samples := 0
	leaderless := 0
	targetEverLeader := false
	watchStart := time.Now()
	for time.Since(watchStart) < watchWindow {
		l := c.Leader()
		samples++
		if l == nil {
			leaderless++
		} else if l.localID == targetID {
			targetEverLeader = true
		}
		time.Sleep(sampleEvery)
	}
	finalLeader := ""
	finalIsTarget := false
	if l := c.Leader(); l != nil {
		finalLeader = string(l.localID)
		finalIsTarget = l.localID == targetID
	}

	// Whatever the transfer did to the leader's transfer state, a client write
	// submitted afterwards shows whether the leader still serves requests.
	applyErr := ""
	applyMs := 0
	configErr := ""
	if l := c.Leader(); l == nil {
		applyErr = "no leader"
		configErr = "no leader"
	} else {
		applyStart := time.Now()
		if err := l.Apply([]byte("post-transfer"), 2*time.Second).Error(); err != nil {
			applyErr = err.Error()
		}
		applyMs = int(time.Since(applyStart) / time.Millisecond)
		if err := l.GetConfiguration().Error(); err != nil {
			configErr = err.Error()
		}
	}

	xgEmit(t, map[string]interface{}{
		"event":                  "xg_result_" + name,
		"case":                   name,
		"mode":                   mode,
		"future_done":            futureDone,
		"future_ok":              futureOK,
		"future_error":           futureErr,
		"future_ms":              futureMS,
		"attempts":               attempts,
		"attempt_errors":         attemptErrors,
		"first_attempt_ok":       firstAttemptOK,
		"first_attempt_error":    firstAttemptErr,
		"target_became_leader":   targetEverLeader,
		"samples":                samples,
		"leaderless_samples":     leaderless,
		"leaderless_ms_at_least": leaderless * int(sampleEvery/time.Millisecond),
		"final_leader":           finalLeader,
		"final_leader_is_target": finalIsTarget,
		"final_leader_is_voter":  finalLeader != "" && !finalIsTarget,
		"post_apply_error":       applyErr,
		"post_apply_ms":          applyMs,
		"post_config_error":      configErr,
	})
	t.Logf("case=%s mode=%s futureOK=%v err=%q targetLeader=%v leaderless=%d final=%q",
		name, mode, futureOK, futureErr, targetEverLeader, leaderless, finalLeader)
}

func TestAssuranceTransferAutomaticVsExplicit(t *testing.T) {
	t.Run("control_automatic_transfer", func(t *testing.T) {
		xgRun(t, "control_automatic_transfer", false)
	})
	t.Run("trigger_explicit_to_demoted", func(t *testing.T) {
		xgRun(t, "trigger_explicit_to_demoted", true)
	})
}

package raft

// Construction notes:
//   * Each case bootstraps its own four-member cluster, demotes one follower and
//     waits until that member's own configuration view reports the non-voter
//     role, so the target is known to be ineligible before the transfer starts.
//   * The single case issues exactly one explicit transfer, sampling the
//     leader's transfer flag before the call, immediately after the call returns
//     its future, after the future completes and after a short settle.
//   * The retry case reproduces the five-attempt sequence and samples the flag
//     before every attempt, so an in-progress error can be attributed either to
//     a prior request still running or to the request that produced it.

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
	"time"
)

func fwEmit(t *testing.T, payload map[string]interface{}) {
	t.Helper()
	data, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal event: %v", err)
	}
	fmt.Println("CA_EVENT " + string(data))
}

type fwSetup struct {
	cluster []*Raft
	leader  *Raft
	target  *Raft
}

func fwPrepare(t *testing.T, name string) (fwSetup, bool) {
	t.Helper()
	conf := inmemConfig(t)
	c := MakeClusterCustom(t, &MakeClusterOpts{Peers: 4, Bootstrap: true, Conf: conf})
	leader := c.Leader()
	if leader == nil {
		c.Close()
		t.Fatalf("no leader")
	}
	var target *Raft
	for _, r := range c.rafts {
		if r.localID != leader.localID {
			target = r
			break
		}
	}
	if target == nil {
		c.Close()
		t.Fatalf("no non-leader peer")
	}
	targetID := target.localID
	if err := leader.DemoteVoter(targetID, 0, 5*time.Second).Error(); err != nil {
		c.Close()
		t.Fatalf("demote: %v", err)
	}
	role := func() string {
		fut := target.GetConfiguration()
		if err := fut.Error(); err != nil {
			return "unknown"
		}
		for _, srv := range fut.Configuration().Servers {
			if srv.ID == targetID {
				if srv.Suffrage == Voter {
					return "voter"
				}
				return "nonvoter"
			}
		}
		return "absent"
	}
	convergeStart := time.Now()
	converged := false
	for time.Since(convergeStart) < 2*time.Second {
		if role() == "nonvoter" {
			converged = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	x := fwSetup{cluster: c.rafts, leader: leader, target: target}
	fwEmit(t, map[string]interface{}{
		"event":         "fw_case_" + name,
		"case":          name,
		"members":       4,
		"demoted":       string(targetID),
		"role_view":     role(),
		"converged":     converged,
		"converge_ms":   int(time.Since(convergeStart) / time.Millisecond),
		"leader_before": string(leader.localID),
	})
	return x, converged
}

func fwWatchLeader(target *Raft, members []*Raft, window time.Duration) (bool, int, int, string) {
	targetEverLeader := false
	leaderless := 0
	samples := 0
	deadline := time.Now().Add(window)
	for time.Now().Before(deadline) {
		samples++
		found := ""
		for _, r := range members {
			if r.State() == Leader {
				found = string(r.localID)
				if r.localID == target.localID {
					targetEverLeader = true
				}
				break
			}
		}
		if found == "" {
			leaderless++
		}
		time.Sleep(10 * time.Millisecond)
	}
	final := ""
	for _, r := range members {
		if r.State() == Leader {
			final = string(r.localID)
			break
		}
	}
	return targetEverLeader, leaderless, samples, final
}

func TestAssuranceTransferFlagWindow(t *testing.T) {
	t.Run("single_explicit_attempt", func(t *testing.T) {
		x, converged := fwPrepare(t, "single_explicit_attempt")
		if !converged {
			t.Fatalf("demotion did not converge on the target")
		}
		before := x.leader.getLeadershipTransferInProgress()
		fut := x.leader.LeadershipTransferToServer(x.target.localID, x.target.localAddr)
		afterCall := x.leader.getLeadershipTransferInProgress()
		start := time.Now()
		done := make(chan error, 1)
		go func() { done <- fut.Error() }()
		var err error
		completed := false
		select {
		case err = <-done:
			completed = true
		case <-time.After(5 * time.Second):
		}
		elapsed := int(time.Since(start) / time.Millisecond)
		afterFuture := x.leader.getLeadershipTransferInProgress()
		time.Sleep(300 * time.Millisecond)
		settled := x.leader.getLeadershipTransferInProgress()
		errText := ""
		if err != nil {
			errText = err.Error()
		}
		targetLed, leaderless, samples, final := fwWatchLeader(x.target, x.cluster, 3*time.Second)
		fwEmit(t, map[string]interface{}{
			"event":                "fw_result_single_explicit_attempt",
			"case":                 "single_explicit_attempt",
			"flag_before":          before,
			"flag_after_call":      afterCall,
			"flag_after_future":    afterFuture,
			"flag_after_300ms":     settled,
			"future_completed":     completed,
			"future_error":         errText,
			"future_ms":            elapsed,
			"attempts":             1,
			"target_became_leader": targetLed,
			"leaderless_samples":   leaderless,
			"samples":              samples,
			"final_leader":         final,
			"final_is_target":      final != "" && final == string(x.target.localID),
		})
	})

	t.Run("retry_sequence_explicit", func(t *testing.T) {
		x, converged := fwPrepare(t, "retry_sequence_explicit")
		if !converged {
			t.Fatalf("demotion did not converge on the target")
		}
		flagBeforeFirst := x.leader.getLeadershipTransferInProgress()
		attemptErrors := []string{}
		flagsBefore := []bool{}
		attempts := 0
		for attempts < 5 {
			current := x.leader
			for _, r := range x.cluster {
				if r.State() == Leader {
					current = r
					break
				}
			}
			flagsBefore = append(flagsBefore, current.getLeadershipTransferInProgress())
			fut := current.LeadershipTransferToServer(x.target.localID, x.target.localAddr)
			attempts++
			done := make(chan error, 1)
			go func() { done <- fut.Error() }()
			var err error
			select {
			case err = <-done:
			case <-time.After(5 * time.Second):
				err = fmt.Errorf("no completion within five seconds")
			}
			text := ""
			if err != nil {
				text = err.Error()
			}
			attemptErrors = append(attemptErrors, text)
			if err == nil || !strings.Contains(text, "in progress") {
				break
			}
			time.Sleep(100 * time.Millisecond)
		}
		targetLed, leaderless, samples, final := fwWatchLeader(x.target, x.cluster, 3*time.Second)
		fwEmit(t, map[string]interface{}{
			"event":                "fw_result_retry_sequence_explicit",
			"case":                 "retry_sequence_explicit",
			"flag_before_first":    flagBeforeFirst,
			"flags_before_attempt": flagsBefore,
			"attempt_errors":       attemptErrors,
			"attempts":             attempts,
			"target_became_leader": targetLed,
			"leaderless_samples":   leaderless,
			"samples":              samples,
			"final_leader":         final,
			"final_is_target":      final != "" && final == string(x.target.localID),
		})
	})
}
